import { useState, useCallback, useMemo } from 'react';
import { Card } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import {
  BoardPackGenerator as BoardPackEngine,
  ReportBookEngine,
  type BoardPackConfig,
  type BoardPackSection,
  type Entity,
  type GenerationProgress,
} from '@/engines/ReportBookEngine';

// ---------------------------------------------------------------------------
// Mock data
// ---------------------------------------------------------------------------

const MOCK_ENTITIES: Entity[] = [
  { id: 'ent-1', name: 'Acme Corp (US)', currency: 'USD', parentId: null },
  { id: 'ent-2', name: 'Acme Europe (UK)', currency: 'GBP', parentId: 'ent-1' },
  { id: 'ent-3', name: 'Acme Asia (JP)', currency: 'JPY', parentId: 'ent-1' },
];

const TEMPLATE_OPTIONS: { value: BoardPackConfig['template']; label: string }[] = [
  { value: 'monthly', label: 'Monthly Board Pack' },
  { value: 'quarterly', label: 'Quarterly Board Pack' },
  { value: 'annual', label: 'Annual Board Pack' },
];

const DEFAULT_SECTIONS = [
  { presetId: 'preset-pl', name: 'Profit & Loss' },
  { presetId: 'preset-bs', name: 'Balance Sheet' },
  { presetId: 'preset-cf', name: 'Cash Flow Statement' },
  { presetId: 'preset-bva', name: 'Budget vs Actual' },
  { presetId: 'preset-kpi', name: 'KPI Dashboard' },
];

// ---------------------------------------------------------------------------
// Sub-components
// ---------------------------------------------------------------------------

interface CoverPagePreviewProps {
  config: BoardPackConfig;
}

function CoverPagePreview({ config }: CoverPagePreviewProps) {
  return (
    <div className="bg-white rounded-lg shadow-2xl p-10 text-slate-900 min-h-[400px] flex flex-col justify-between">
      <div>
        {config.logoUrl && (
          <img src={config.logoUrl} alt="Company logo" className="h-12 mb-8" />
        )}
        <h1 className="text-3xl font-bold mb-2">{config.title}</h1>
        {config.subtitle && <p className="text-lg text-slate-500 mb-6">{config.subtitle}</p>}
      </div>

      <div className="space-y-1 text-sm text-slate-600">
        <p>{config.companyName}</p>
        <p>{config.entityName}</p>
        <p>{config.coverDate}</p>
      </div>
    </div>
  );
}

interface SectionPreviewProps {
  section: BoardPackSection;
  sectionIndex: number;
}

function SectionPreview({ section, sectionIndex }: SectionPreviewProps) {
  return (
    <div className="space-y-2">
      <h4 className="text-sm font-semibold text-white">
        {sectionIndex + 1}. {section.title}
      </h4>
      <div className="space-y-1">
        {section.reports.map((report, ri) => (
          <div
            key={ri}
            className="flex items-center justify-between text-xs text-slate-400 bg-slate-800/30 rounded px-2 py-1"
          >
            <span>
              {report.entityName} — {report.reportName}
            </span>
            <span className="text-slate-500">
              {report.data.rows.length} rows
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

interface ProgressBarProps {
  progress: GenerationProgress;
}

function ProgressBar({ progress }: ProgressBarProps) {
  const pct = progress.total > 0 ? Math.round((progress.completed / progress.total) * 100) : 0;

  return (
    <div className="space-y-2">
      <div className="flex justify-between text-xs text-slate-400">
        <span>
          {progress.currentReport && `${progress.currentReport} — ${progress.currentEntity}`}
        </span>
        <span>
          {progress.completed}/{progress.total} ({pct}%)
        </span>
      </div>
      <div className="h-2 rounded-full bg-slate-700 overflow-hidden">
        <div
          className={`h-full rounded-full transition-all duration-300 ${
            progress.status === 'error' ? 'bg-red-500' : 'bg-blue-500'
          }`}
          style={{ width: `${pct}%` }}
        />
      </div>
      {progress.errors.length > 0 && (
        <ul className="text-xs text-red-400 space-y-0.5 max-h-24 overflow-auto">
          {progress.errors.map((err, i) => (
            <li key={i}>{err}</li>
          ))}
        </ul>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Main Component
// ---------------------------------------------------------------------------

export function BoardPackGenerator() {
  const [bookEngine] = useState(() => {
    const engine = new ReportBookEngine();
    const book = engine.createBook('Board Pack', 'Monthly board pack');
    // Pre-populate with default sections
    for (const section of DEFAULT_SECTIONS) {
      engine.addEntry(book.id, {
        reportName: section.name,
        templateId: section.presetId,
        entityIds: MOCK_ENTITIES.map((e) => e.id),
        variables: { period: 'May 2026' },
        enabled: true,
      });
    }
    return engine;
  });

  const [packEngine] = useState(() => new BoardPackEngine(bookEngine));

  const [config, setConfig] = useState<BoardPackConfig>({
    title: 'Monthly Board Pack',
    subtitle: 'Consolidated Financial Review',
    template: 'monthly',
    companyName: 'Acme Corporation',
    coverDate: 'May 2026',
    entityName: 'All Entities (Consolidated)',
    includeTableOfContents: true,
    includeExecutiveSummary: true,
  });

  const [sections, setSections] = useState<BoardPackSection[]>([]);
  const [progress, setProgress] = useState<GenerationProgress | null>(null);
  const [isGenerated, setIsGenerated] = useState(false);

  const book = useMemo(() => bookEngine.listBooks()[0], [bookEngine]);

  // --- Handlers ---

  const handleConfigChange = useCallback(
    (field: keyof BoardPackConfig, value: string | boolean) => {
      setConfig((prev) => ({ ...prev, [field]: value }));
    },
    [],
  );

  const handleGenerate = useCallback(async () => {
    if (!book) return;

    setProgress({
      total: 0,
      completed: 0,
      currentEntity: '',
      currentReport: '',
      status: 'pending',
      errors: [],
    });
    setIsGenerated(false);

    try {
      const result = await packEngine.generateBoardPack(
        book.id,
        MOCK_ENTITIES,
        config,
        setProgress,
      );
      setSections(result.sections);
      setIsGenerated(true);
    } catch {
      // errors captured in progress
    }
  }, [book, config, packEngine]);

  const handleExportPDF = useCallback(() => {
    if (!isGenerated) return;
    // PDF export handled by ExportEngine
  }, [isGenerated, sections]);

  const handleExportExcel = useCallback(() => {
    if (!isGenerated) return;
    // Excel export handled by ExportEngine
  }, [isGenerated, sections]);

  // --- Computed ---

  const totalReports = useMemo(
    () =>
      book?.entries
        .filter((e) => e.enabled)
        .reduce((s, e) => s + e.entityIds.length, 0) ?? 0,
    [book],
  );

  // --- Render ---

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
      {/* LEFT: Configuration */}
      <div className="lg:col-span-4 space-y-6">
        <Card className="p-4 space-y-4">
          <h3 className="text-sm font-semibold text-white">Board Pack Configuration</h3>

          {/* Template selector */}
          <div>
            <label className="block text-xs text-slate-400 mb-1">Template</label>
            <select
              value={config.template}
              onChange={(e) => handleConfigChange('template', e.target.value)}
              className="w-full bg-slate-800 border border-slate-700 rounded text-sm text-white px-3 py-2"
            >
              {TEMPLATE_OPTIONS.map((opt) => (
                <option key={opt.value} value={opt.value}>
                  {opt.label}
                </option>
              ))}
            </select>
          </div>

          {/* Title */}
          <div>
            <label className="block text-xs text-slate-400 mb-1">Title</label>
            <input
              type="text"
              value={config.title}
              onChange={(e) => handleConfigChange('title', e.target.value)}
              className="w-full bg-slate-800 border border-slate-700 rounded text-sm text-white px-3 py-2"
            />
          </div>

          {/* Subtitle */}
          <div>
            <label className="block text-xs text-slate-400 mb-1">Subtitle</label>
            <input
              type="text"
              value={config.subtitle ?? ''}
              onChange={(e) => handleConfigChange('subtitle', e.target.value)}
              className="w-full bg-slate-800 border border-slate-700 rounded text-sm text-white px-3 py-2"
            />
          </div>

          {/* Company */}
          <div>
            <label className="block text-xs text-slate-400 mb-1">Company Name</label>
            <input
              type="text"
              value={config.companyName}
              onChange={(e) => handleConfigChange('companyName', e.target.value)}
              className="w-full bg-slate-800 border border-slate-700 rounded text-sm text-white px-3 py-2"
            />
          </div>

          {/* Entity */}
          <div>
            <label className="block text-xs text-slate-400 mb-1">Entity</label>
            <select
              value={config.entityName}
              onChange={(e) => handleConfigChange('entityName', e.target.value)}
              className="w-full bg-slate-800 border border-slate-700 rounded text-sm text-white px-3 py-2"
            >
              <option value="All Entities (Consolidated)">All Entities (Consolidated)</option>
              {MOCK_ENTITIES.map((ent) => (
                <option key={ent.id} value={ent.name}>
                  {ent.name}
                </option>
              ))}
            </select>
          </div>

          {/* Date */}
          <div>
            <label className="block text-xs text-slate-400 mb-1">Cover Date</label>
            <input
              type="text"
              value={config.coverDate}
              onChange={(e) => handleConfigChange('coverDate', e.target.value)}
              className="w-full bg-slate-800 border border-slate-700 rounded text-sm text-white px-3 py-2"
            />
          </div>

          {/* Options */}
          <div className="space-y-2">
            <label className="flex items-center gap-2 text-xs text-slate-400">
              <input
                type="checkbox"
                checked={config.includeTableOfContents}
                onChange={(e) => handleConfigChange('includeTableOfContents', e.target.checked)}
                className="rounded"
              />
              Include Table of Contents
            </label>
            <label className="flex items-center gap-2 text-xs text-slate-400">
              <input
                type="checkbox"
                checked={config.includeExecutiveSummary}
                onChange={(e) => handleConfigChange('includeExecutiveSummary', e.target.checked)}
                className="rounded"
              />
              Include Executive Summary
            </label>
          </div>

          {/* Generate */}
          <div className="pt-2 space-y-2">
            <Button
              onClick={handleGenerate}
              disabled={progress?.status === 'running'}
              className="w-full"
            >
              {progress?.status === 'running'
                ? 'Generating...'
                : `Generate Board Pack (${totalReports} reports)`}
            </Button>
            {progress && <ProgressBar progress={progress} />}
          </div>
        </Card>

        {/* Export buttons */}
        {isGenerated && (
          <Card className="p-4 space-y-3">
            <h3 className="text-sm font-semibold text-white">Export</h3>
            <div className="flex gap-2">
              <Button onClick={handleExportPDF} className="flex-1">
                Export PDF
              </Button>
              <Button onClick={handleExportExcel} variant="secondary" className="flex-1">
                Export Excel
              </Button>
            </div>
            <p className="text-xs text-slate-500">
              PDF includes cover page, table of contents, executive summary, and all report
              sections with page breaks.
            </p>
          </Card>
        )}
      </div>

      {/* CENTER + RIGHT: Preview */}
      <div className="lg:col-span-8 space-y-6">
        {/* Cover page preview */}
        <div>
          <h3 className="text-sm font-semibold text-white mb-3">Cover Page Preview</h3>
          <CoverPagePreview config={config} />
        </div>

        {/* Table of contents */}
        {config.includeTableOfContents && (
          <Card className="p-4 space-y-2">
            <h3 className="text-sm font-semibold text-white">Table of Contents</h3>
            <ol className="space-y-1 text-xs text-slate-400 list-decimal list-inside">
              {config.includeExecutiveSummary && <li>Executive Summary</li>}
              {book?.entries
                .filter((e) => e.enabled)
                .map((entry, i) => (
                  <li key={entry.id}>
                    {i + (config.includeExecutiveSummary ? 2 : 1)}. {entry.reportName}
                  </li>
                ))}
            </ol>
          </Card>
        )}

        {/* Generated sections */}
        {isGenerated && sections.length > 0 && (
          <Card className="p-4 space-y-4">
            <h3 className="text-sm font-semibold text-white">
              Generated Sections ({sections.length})
            </h3>
            <div className="space-y-4">
              {sections.map((section, i) => (
                <SectionPreview key={section.id} section={section} sectionIndex={i} />
              ))}
            </div>
          </Card>
        )}

        {/* Empty state */}
        {!isGenerated && (
          <div className="text-center py-16 text-slate-500 text-sm">
            Configure the board pack on the left and click &quot;Generate Board Pack&quot; to preview
            the output.
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useCallback, useMemo } from 'react';
import {
  GripVertical, Plus, Trash2, Settings, Eye, Save, Undo2, Redo2,
  Layers, Columns, Rows,
} from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { cn } from '@/utils/cn';
import { ReportGrid } from './ReportGrid';
import {
  ReportBuilderEngine,
  type ReportDefinition,
  type ReportLayout,
  type RowType,
  type ColumnType,
  type PeriodType,
  type CubeData,
} from '@/engines/ReportBuilderEngine';

/* ────────────────── props ────────────────── */

export interface ReportBuilderProps {
  initialReport?: ReportDefinition;
  cubeData?: CubeData;
  onSave?: (report: ReportDefinition) => void;
  onExportPDF?: (report: ReportDefinition) => void;
  onExportExcel?: (report: ReportDefinition) => void;
  onExportCSV?: (report: ReportDefinition) => void;
  className?: string;
}

/* ────────────────── draggable item ────────────────── */

interface DragItem {
  type: 'row-type' | 'column-type';
  value: string;
}

/* ────────────────── available items ────────────────── */

const ROW_TYPES: Array<{ type: RowType; label: string; icon: string }> = [
  { type: 'header', label: 'Header Row', icon: 'H' },
  { type: 'data', label: 'Data Row', icon: 'D' },
  { type: 'subtotal', label: 'Subtotal Row', icon: 'S' },
  { type: 'total', label: 'Total Row', icon: 'T' },
  { type: 'blank', label: 'Blank Row', icon: '—' },
];

const COLUMN_TYPES: Array<{ type: ColumnType; label: string; period?: PeriodType }> = [
  { type: 'label', label: 'Label Column' },
  { type: 'period', label: 'Actual Column', period: 'actual' },
  { type: 'period', label: 'Budget Column', period: 'budget' },
  { type: 'period', label: 'Forecast Column', period: 'forecast' },
  { type: 'period', label: 'Variance Column', period: 'variance' },
  { type: 'custom', label: 'Custom Column' },
];

/* ────────────────── main component ────────────────── */

export function ReportBuilder({
  initialReport,
  cubeData = {},
  onSave,
  onExportPDF,
  onExportExcel,
  onExportCSV,
  className,
}: ReportBuilderProps) {
  const [report, setReport] = useState<ReportDefinition>(() =>
    initialReport ?? ReportBuilderEngine.createReport('New Report', 'custom', 'user')
  );
  const [history, setHistory] = useState<ReportDefinition[]>([report]);
  const [historyIndex, setHistoryIndex] = useState(0);
  const [activePanel, setActivePanel] = useState<'rows' | 'columns' | 'properties'>('rows');
  const [previewMode, setPreviewMode] = useState(false);
  const [selectedRowIndex, setSelectedRowIndex] = useState<number | null>(null);
  const [selectedColIndex, setSelectedColIndex] = useState<number | null>(null);

  /* ── undo / redo ── */
  const pushHistory = useCallback(
    (next: ReportDefinition) => {
      setHistory((prev) => [...prev.slice(0, historyIndex + 1), next]);
      setHistoryIndex((i) => i + 1);
      setReport(next);
    },
    [historyIndex]
  );

  const undo = useCallback(() => {
    if (historyIndex > 0) {
      const next = historyIndex - 1;
      setHistoryIndex(next);
      setReport(history[next]);
    }
  }, [historyIndex, history]);

  const redo = useCallback(() => {
    if (historyIndex < history.length - 1) {
      const next = historyIndex + 1;
      setHistoryIndex(next);
      setReport(history[next]);
    }
  }, [historyIndex, history]);

  /* ── layout mutation helpers ── */
  const updateLayout = useCallback(
    (updater: (layout: ReportLayout) => ReportLayout) => {
      const newLayout = updater(report.layout);
      pushHistory({
        ...report,
        layout: newLayout,
        updatedAt: new Date().toISOString(),
        version: report.version + 1,
      });
    },
    [report, pushHistory]
  );

  /* ── row operations ── */
  const addRow = useCallback(
    (type: RowType) => {
      updateLayout((layout) => ReportBuilderEngine.addRow(layout, type));
    },
    [updateLayout]
  );

  const removeRow = useCallback(
    (rowId: string) => {
      updateLayout((layout) => ReportBuilderEngine.removeRow(layout, rowId));
      setSelectedRowIndex(null);
    },
    [updateLayout]
  );

  /* ── column operations ── */
  const addColumn = useCallback(
    (colType: ColumnType, period?: PeriodType) => {
      updateLayout((layout) =>
        ReportBuilderEngine.addColumn(layout, {
          type: colType,
          header: colType === 'label' ? 'Label' : period ? period.charAt(0).toUpperCase() + period.slice(1) : 'Custom',
          width: colType === 'label' ? 220 : 130,
          period,
        })
      );
    },
    [updateLayout]
  );

  const removeColumn = useCallback(
    (colId: string) => {
      updateLayout((layout) => ReportBuilderEngine.removeColumn(layout, colId));
      setSelectedColIndex(null);
    },
    [updateLayout]
  );

  /* ── row/column name editing ── */
  const updateRowLabel = useCallback(
    (rowIndex: number, text: string) => {
      updateLayout((layout) => {
        const row = layout.rows[rowIndex];
        if (!row) return layout;
        const labelColIdx = layout.columns.findIndex((c) => c.type === 'label');
        if (labelColIdx === -1) return layout;
        return ReportBuilderEngine.updateCell(layout, rowIndex, labelColIdx, {
          type: 'text',
          content: { text },
        });
      });
    },
    [updateLayout]
  );

  const updateColumnHeader = useCallback(
    (colIndex: number, header: string) => {
      updateLayout((layout) => {
        const columns = layout.columns.map((c, i) =>
          i === colIndex ? { ...c, header } : c
        );
        return { ...layout, columns };
      });
    },
    [updateLayout]
  );

  /* ── report metadata ── */
  const updateName = useCallback(
    (name: string) => {
      pushHistory(ReportBuilderEngine.updateReport(report, { name }));
    },
    [report, pushHistory]
  );

  /* ── save ── */
  const handleSave = useCallback(() => {
    onSave?.(report);
  }, [report, onSave]);

  /* ── drag and drop ── */
  const handleDragStart = useCallback(
    (e: React.DragEvent, item: DragItem) => {
      e.dataTransfer.setData('application/json', JSON.stringify(item));
      e.dataTransfer.effectAllowed = 'copy';
    },
    []
  );

  const handleDrop = useCallback(
    (e: React.DragEvent, target: 'rows' | 'columns') => {
      e.preventDefault();
      try {
        const item: DragItem = JSON.parse(e.dataTransfer.getData('application/json'));
        if (target === 'rows' && item.type === 'row-type') {
          addRow(item.value as RowType);
        } else if (target === 'columns' && item.type === 'column-type') {
          const colDef = COLUMN_TYPES.find((c) => c.label === item.value);
          if (colDef) addColumn(colDef.type, colDef.period);
        }
      } catch {
        // ignore invalid drag data
      }
    },
    [addRow, addColumn]
  );

  /* ── render ── */
  const validation = useMemo(() => ReportBuilderEngine.validateReport(report), [report]);
  const errors = validation.errors;

  return (
    <div className={cn('flex flex-col h-full', className)} role="region" aria-label="Report Builder">
      {/* Toolbar */}
      <div className="flex items-center justify-between px-4 py-2 border-b border-slate-800 bg-slate-900/50">
        <div className="flex items-center gap-3">
          <input
            type="text"
            value={report.name}
            onChange={(e) => updateName(e.target.value)}
            className="bg-transparent text-lg font-semibold text-white border-b border-transparent hover:border-slate-600 focus:border-blue-500 focus:outline-none px-1"
            aria-label="Report name"
          />
          {errors.length > 0 && (
            <span className="text-xs text-amber-400 bg-amber-500/10 px-2 py-0.5 rounded">
              {errors.length} issue{errors.length > 1 ? 's' : ''}
            </span>
          )}
        </div>
        <div className="flex items-center gap-1">
          <Button size="sm" variant="ghost" onClick={undo} disabled={historyIndex === 0} aria-label="Undo">
            <Undo2 className="h-4 w-4" />
          </Button>
          <Button size="sm" variant="ghost" onClick={redo} disabled={historyIndex === history.length - 1} aria-label="Redo">
            <Redo2 className="h-4 w-4" />
          </Button>
          <div className="w-px h-5 bg-slate-700 mx-1" />
          <Button size="sm" variant="ghost" onClick={() => setPreviewMode(!previewMode)} aria-label={previewMode ? 'Switch to edit mode' : 'Switch to preview mode'}>
            <Eye className="h-4 w-4 mr-1.5" />
            {previewMode ? 'Edit' : 'Preview'}
          </Button>
          <Button size="sm" onClick={handleSave}>
            <Save className="h-4 w-4 mr-1.5" />
            Save
          </Button>
        </div>
      </div>

      {/* Body */}
      {previewMode ? (
        <div className="flex-1 overflow-auto p-6">
          <ReportGrid
            layout={report.layout}
            cubeData={cubeData}
            onExportPDF={() => onExportPDF?.(report)}
            onExportExcel={() => onExportExcel?.(report)}
            onExportCSV={() => onExportCSV?.(report)}
          />
        </div>
      ) : (
        <div className="flex flex-1 overflow-hidden">
          {/* Left Panel */}
          <div className="w-56 border-r border-slate-800 flex flex-col overflow-hidden">
            <div className="flex border-b border-slate-800">
              <button
                className={cn(
                  'flex-1 px-3 py-2 text-xs font-medium text-center transition-colors',
                  activePanel === 'rows' ? 'text-blue-400 border-b-2 border-blue-400' : 'text-slate-400 hover:text-white'
                )}
                onClick={() => setActivePanel('rows')}
              >
                <Rows className="h-3.5 w-3.5 inline mr-1" />
                Rows
              </button>
              <button
                className={cn(
                  'flex-1 px-3 py-2 text-xs font-medium text-center transition-colors',
                  activePanel === 'columns' ? 'text-blue-400 border-b-2 border-blue-400' : 'text-slate-400 hover:text-white'
                )}
                onClick={() => setActivePanel('columns')}
              >
                <Columns className="h-3.5 w-3.5 inline mr-1" />
                Cols
              </button>
              <button
                className={cn(
                  'flex-1 px-3 py-2 text-xs font-medium text-center transition-colors',
                  activePanel === 'properties' ? 'text-blue-400 border-b-2 border-blue-400' : 'text-slate-400 hover:text-white'
                )}
                onClick={() => setActivePanel('properties')}
              >
                <Settings className="h-3.5 w-3.5 inline mr-1" />
                Props
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-3 space-y-2">
              {activePanel === 'rows' && (
                <>
                  <p className="text-xs text-slate-500 mb-2">Drag to add rows</p>
                  {ROW_TYPES.map((rt) => (
                    <div
                      key={rt.type}
                      draggable
                      onDragStart={(e) => handleDragStart(e, { type: 'row-type', value: rt.type })}
                      className="flex items-center gap-2 px-3 py-2 rounded-lg border border-slate-700 bg-slate-800/50 cursor-grab hover:border-blue-500 hover:bg-slate-800 transition-colors text-sm"
                    >
                      <GripVertical className="h-3.5 w-3.5 text-slate-500" />
                      <span className="text-xs font-mono bg-slate-700 px-1.5 py-0.5 rounded">{rt.icon}</span>
                      <span className="text-slate-300">{rt.label}</span>
                    </div>
                  ))}
                </>
              )}

              {activePanel === 'columns' && (
                <>
                  <p className="text-xs text-slate-500 mb-2">Drag to add columns</p>
                  {COLUMN_TYPES.map((ct) => (
                    <div
                      key={ct.label}
                      draggable
                      onDragStart={(e) => handleDragStart(e, { type: 'column-type', value: ct.label })}
                      className="flex items-center gap-2 px-3 py-2 rounded-lg border border-slate-700 bg-slate-800/50 cursor-grab hover:border-blue-500 hover:bg-slate-800 transition-colors text-sm"
                    >
                      <GripVertical className="h-3.5 w-3.5 text-slate-500" />
                      <span className="text-slate-300">{ct.label}</span>
                    </div>
                  ))}
                </>
              )}

              {activePanel === 'properties' && (
                <div className="space-y-4">
                  <div>
                    <label className="text-xs text-slate-400 block mb-1">Report Name</label>
                    <input
                      type="text"
                      value={report.name}
                      onChange={(e) => updateName(e.target.value)}
                      className="w-full bg-slate-800 border border-slate-700 rounded px-2 py-1.5 text-sm text-white"
                    />
                  </div>
                  <div>
                    <label className="text-xs text-slate-400 block mb-1">Description</label>
                    <textarea
                      value={report.description}
                      onChange={(e) =>
                        pushHistory(ReportBuilderEngine.updateReport(report, { description: e.target.value }))
                      }
                      className="w-full bg-slate-800 border border-slate-700 rounded px-2 py-1.5 text-sm text-white resize-none"
                      rows={3}
                    />
                  </div>

                  {errors.length > 0 && (
                    <div className="mt-4 space-y-1">
                      <p className="text-xs font-medium text-amber-400">Validation Issues</p>
                      {errors.map((err: string, i: number) => (
                        <p key={i} className="text-xs text-amber-400/80">• {err}</p>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>

          {/* Center — Layout Editor */}
          <div className="flex-1 flex flex-col overflow-hidden">
            <div
              className="flex-1 overflow-y-auto"
              onDragOver={(e) => e.preventDefault()}
              onDrop={(e) => handleDrop(e, 'rows')}
            >
              <div className="p-4 space-y-1">
                <div className="flex items-center justify-between mb-2">
                  <h3 className="text-xs font-semibold text-slate-400 uppercase flex items-center gap-1.5">
                    <Rows className="h-3.5 w-3.5" />
                    Rows ({report.layout.rows.length})
                  </h3>
                  <Button size="sm" variant="ghost" onClick={() => addRow('data')}>
                    <Plus className="h-3.5 w-3.5 mr-1" />
                    Add Row
                  </Button>
                </div>

                {report.layout.rows.length === 0 ? (
                  <div className="text-center py-8 text-slate-500 text-sm border-2 border-dashed border-slate-700 rounded-lg">
                    Drag row types here or click Add Row
                  </div>
                ) : (
                  report.layout.rows.map((row, ri) => (
                    <div
                      key={row.id}
                      role="button"
                      tabIndex={0}
                      className={cn(
                        'flex items-center gap-2 px-3 py-1.5 rounded border text-sm transition-colors cursor-pointer',
                        selectedRowIndex === ri
                          ? 'border-blue-500 bg-blue-500/10'
                          : 'border-slate-700 bg-slate-800/30 hover:border-slate-600'
                      )}
                      onClick={() => setSelectedRowIndex(ri)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' || e.key === ' ') {
                          e.preventDefault();
                          setSelectedRowIndex(ri);
                        }
                      }}
                    >
                      <GripVertical className="h-3.5 w-3.5 text-slate-500 flex-shrink-0" />
                      <span
                        className={cn(
                          'text-xs font-mono px-1.5 py-0.5 rounded flex-shrink-0',
                          row.type === 'total' ? 'bg-green-500/20 text-green-400' :
                          row.type === 'subtotal' ? 'bg-blue-500/20 text-blue-400' :
                          row.type === 'header' ? 'bg-purple-500/20 text-purple-400' :
                          row.type === 'blank' ? 'bg-slate-600 text-slate-400' :
                          'bg-slate-700 text-slate-300'
                        )}
                      >
                        {row.type.charAt(0).toUpperCase()}
                      </span>
                      <span className="text-slate-300 truncate flex-1">
                        {(row.cells.find((_, ci) => report.layout.columns[ci]?.type === 'label')?.content as { content?: { text?: string } })?.content?.text ?? row.type}
                      </span>
                      {row.grouping && (
                        <Layers className="h-3 w-3 text-slate-500 flex-shrink-0" />
                      )}
                      <button
                        className="text-slate-500 hover:text-red-400 flex-shrink-0"
                        onClick={(e) => {
                          e.stopPropagation();
                          removeRow(row.id);
                        }}
                        aria-label={`Remove row ${ri + 1}`}
                      >
                        <Trash2 className="h-3.5 w-3.5" />
                      </button>
                    </div>
                  ))
                )}
              </div>

              {/* Column list */}
              <div
                className="px-4 pb-4"
                onDragOver={(e) => e.preventDefault()}
                onDrop={(e) => handleDrop(e, 'columns')}
              >
                <div className="flex items-center justify-between mb-2">
                  <h3 className="text-xs font-semibold text-slate-400 uppercase flex items-center gap-1.5">
                    <Columns className="h-3.5 w-3.5" />
                    Columns ({report.layout.columns.length})
                  </h3>
                  <Button size="sm" variant="ghost" onClick={() => addColumn('period', 'actual')}>
                    <Plus className="h-3.5 w-3.5 mr-1" />
                    Add Column
                  </Button>
                </div>

                {report.layout.columns.length === 0 ? (
                  <div className="text-center py-6 text-slate-500 text-sm border-2 border-dashed border-slate-700 rounded-lg">
                    Drag column types here or click Add Column
                  </div>
                ) : (
                  <div className="flex flex-wrap gap-1">
                    {report.layout.columns.map((col, ci) => (
                      <div
                        key={col.id}
                        role="button"
                        tabIndex={0}
                        className={cn(
                          'flex items-center gap-1.5 px-2.5 py-1 rounded border text-xs transition-colors cursor-pointer',
                          selectedColIndex === ci
                            ? 'border-blue-500 bg-blue-500/10'
                            : 'border-slate-700 bg-slate-800/30 hover:border-slate-600'
                        )}
                        onClick={() => setSelectedColIndex(ci)}
                        onKeyDown={(e) => {
                          if (e.key === 'Enter' || e.key === ' ') {
                            e.preventDefault();
                            setSelectedColIndex(ci);
                          }
                        }}
                      >
                        <span
                          className={cn(
                            'font-mono px-1 py-0.5 rounded',
                            col.type === 'label' ? 'bg-purple-500/20 text-purple-400' :
                            col.period === 'actual' ? 'bg-green-500/20 text-green-400' :
                            col.period === 'budget' ? 'bg-blue-500/20 text-blue-400' :
                            col.period === 'variance' ? 'bg-amber-500/20 text-amber-400' :
                            'bg-slate-600 text-slate-400'
                          )}
                        >
                          {col.type === 'label' ? 'L' : col.period?.charAt(0).toUpperCase() ?? 'C'}
                        </span>
                        <span className="text-slate-300">{col.header}</span>
                        <button
                          className="text-slate-500 hover:text-red-400 ml-1"
                          onClick={(e) => {
                            e.stopPropagation();
                            removeColumn(col.id);
                          }}
                          aria-label={`Remove column ${col.header}`}
                        >
                          <Trash2 className="h-3 w-3" />
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>

            {/* Selected item properties */}
            {(selectedRowIndex !== null || selectedColIndex !== null) && (
              <div className="border-t border-slate-800 p-4 bg-slate-900/30">
                {selectedRowIndex !== null && report.layout.rows[selectedRowIndex] && (
                  <div className="space-y-2">
                    <p className="text-xs font-medium text-slate-400">
                      Row {selectedRowIndex + 1} — {report.layout.rows[selectedRowIndex].type}
                    </p>
                    <div className="flex gap-2">
                      <input
                        type="text"
                        value={
                          (report.layout.rows[selectedRowIndex].cells.find(
                            (_, ci) => report.layout.columns[ci]?.type === 'label'
                          )?.content as { content?: { text?: string } })?.content?.text ?? ''
                        }
                        onChange={(e) => updateRowLabel(selectedRowIndex, e.target.value)}
                        placeholder="Row label..."
                        className="flex-1 bg-slate-800 border border-slate-700 rounded px-2 py-1 text-sm text-white"
                      />
                      <select
                        value={report.layout.rows[selectedRowIndex].type}
                        onChange={(e) => {
                          const newType = e.target.value as RowType;
                          updateLayout((layout) => {
                            const rows = layout.rows.map((r, i) =>
                              i === selectedRowIndex ? { ...r, type: newType } : r
                            );
                            return { ...layout, rows };
                          });
                        }}
                        className="bg-slate-800 border border-slate-700 rounded px-2 py-1 text-sm text-white"
                      >
                        {ROW_TYPES.map((rt) => (
                          <option key={rt.type} value={rt.type}>{rt.label}</option>
                        ))}
                      </select>
                    </div>
                  </div>
                )}
                {selectedColIndex !== null && report.layout.columns[selectedColIndex] && (
                  <div className="space-y-2">
                    <p className="text-xs font-medium text-slate-400">
                      Column {selectedColIndex + 1} — {report.layout.columns[selectedColIndex].type}
                    </p>
                    <div className="flex gap-2">
                      <input
                        type="text"
                        value={report.layout.columns[selectedColIndex].header}
                        onChange={(e) => updateColumnHeader(selectedColIndex, e.target.value)}
                        placeholder="Column header..."
                        className="flex-1 bg-slate-800 border border-slate-700 rounded px-2 py-1 text-sm text-white"
                      />
                      <input
                        type="number"
                        value={report.layout.columns[selectedColIndex].width}
                        onChange={(e) => {
                          const width = parseInt(e.target.value, 10) || 100;
                          updateLayout((layout) =>
                            ReportBuilderEngine.setColumnWidth(layout, report.layout.columns[selectedColIndex].id, width)
                          );
                        }}
                        className="w-20 bg-slate-800 border border-slate-700 rounded px-2 py-1 text-sm text-white"
                        min={40}
                        aria-label="Column width"
                      />
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Right Panel — Live Preview */}
          <div className="w-[420px] border-l border-slate-800 overflow-y-auto p-4 bg-slate-950/50">
            <h3 className="text-xs font-semibold text-slate-400 uppercase mb-3 flex items-center gap-1.5">
              <Eye className="h-3.5 w-3.5" />
              Live Preview
            </h3>
            <div className="origin-top-left scale-[0.65] w-[154%]">
              <ReportGrid
                layout={report.layout}
                cubeData={cubeData}
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useCallback } from 'react';
import type { ExportTemplate, TemplateSection, TemplateStyle, TemplateType } from '@/engines/ExportTemplateEngine';

interface TemplateDesignerProps {
  template?: ExportTemplate;
  onSave: (template: ExportTemplate) => void;
  onCancel: () => void;
}

const SECTION_TYPES: Array<{ value: TemplateSection['type']; label: string }> = [
  { value: 'cover', label: 'Cover Page' },
  { value: 'kpi_summary', label: 'KPI Summary' },
  { value: 'table', label: 'Data Table' },
  { value: 'text', label: 'Text Block' },
  { value: 'page_break', label: 'Page Break' },
];

const TEMPLATE_TYPES: Array<{ value: TemplateType; label: string }> = [
  { value: 'board_pack', label: 'Board Pack' },
  { value: 'pl_statement', label: 'P&L Statement' },
  { value: 'balance_sheet', label: 'Balance Sheet' },
  { value: 'cash_flow', label: 'Cash Flow' },
  { value: 'budget_vs_actual', label: 'Budget vs Actual' },
  { value: 'kpi_summary', label: 'KPI Summary' },
];

let nextId = 1;

export function TemplateDesigner({ template, onSave, onCancel }: TemplateDesignerProps) {
  const [name, setName] = useState(template?.name ?? 'New Template');
  const [description, setDescription] = useState(template?.description ?? '');
  const [type, setType] = useState<TemplateType>(template?.type ?? 'board_pack');
  const [sections, setSections] = useState<TemplateSection[]>(template?.sections ?? []);
  const [style, setStyle] = useState<TemplateStyle>(template?.style ?? {
    primaryColor: '#1E3A5F',
    secondaryColor: '#4A90D9',
    fontFamily: 'helvetica',
    headerFontSize: 10,
    bodyFontSize: 8,
    companyName: 'FinPlan Pro',
  });
  const [selectedSection, setSelectedSection] = useState<string | null>(null);

  const addSection = useCallback((sectionType: TemplateSection['type']) => {
    const id = `section-${Date.now()}-${nextId++}`;
    const newSection: TemplateSection = {
      id,
      type: sectionType,
      title: sectionType === 'cover' ? 'Cover Page' : sectionType === 'page_break' ? '' : `New ${sectionType.replace(/_/g, ' ')}`,
      order: sections.length,
      config: sectionType === 'cover' ? { title: name, subtitle: '', confidential: true }
        : sectionType === 'kpi_summary' ? { kpis: [] }
        : sectionType === 'table' ? { headers: [], rows: [] }
        : sectionType === 'text' ? { content: '' }
        : {},
    };
    setSections((prev) => [...prev, newSection]);
    setSelectedSection(id);
  }, [sections.length, name]);

  const removeSection = useCallback((id: string) => {
    setSections((prev) => prev.filter((s) => s.id !== id));
    if (selectedSection === id) setSelectedSection(null);
  }, [selectedSection]);

  const moveSection = useCallback((id: string, direction: 'up' | 'down') => {
    setSections((prev) => {
      const idx = prev.findIndex((s) => s.id === id);
      if (idx < 0) return prev;
      const target = direction === 'up' ? idx - 1 : idx + 1;
      if (target < 0 || target >= prev.length) return prev;
      const next = [...prev];
      [next[idx], next[target]] = [next[target], next[idx]];
      return next.map((s, i) => ({ ...s, order: i }));
    });
  }, []);

  const updateSectionTitle = useCallback((id: string, title: string) => {
    setSections((prev) => prev.map((s) => (s.id === id ? { ...s, title } : s)));
  }, []);

  const handleSave = useCallback(() => {
    const now = new Date().toISOString();
    onSave({
      id: template?.id ?? `tpl-custom-${Date.now()}`,
      name,
      type,
      description,
      sections: sections.map((s, i) => ({ ...s, order: i })),
      style,
      variables: [
        { key: 'entity', label: 'Entity', defaultValue: 'Company Name' },
        { key: 'period', label: 'Period', defaultValue: 'FY 2026' },
        { key: 'currency', label: 'Currency', defaultValue: 'USD' },
        { key: 'date', label: 'Date', defaultValue: new Date().toLocaleDateString() },
        { key: 'preparedBy', label: 'Prepared By', defaultValue: 'Finance Team' },
      ],
      createdAt: template?.createdAt ?? now,
      updatedAt: now,
    });
  }, [name, type, description, sections, style, template, onSave]);

  const active = sections.find((s) => s.id === selectedSection);

  return (
    <div className="flex h-full">
      {/* Left: Section list */}
      <div className="w-64 border-r border-gray-200 dark:border-gray-700 p-4 overflow-y-auto">
        <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3">Sections</h3>
        <div className="space-y-1 mb-4">
          {sections.map((section) => (
            <div
              key={section.id}
              role="button"
              tabIndex={0}
              className={`flex items-center gap-2 px-2 py-1.5 rounded cursor-pointer text-sm ${
                selectedSection === section.id
                  ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300'
                  : 'hover:bg-gray-100 dark:hover:bg-gray-800 text-gray-600 dark:text-gray-400'
              }`}
              onClick={() => setSelectedSection(section.id)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault();
                  setSelectedSection(section.id);
                }
              }}
            >
              <span className="flex-1 truncate">{section.title || section.type}</span>
              <button
                className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                onClick={(e) => { e.stopPropagation(); moveSection(section.id, 'up'); }}
              >
                ↑
              </button>
              <button
                className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                onClick={(e) => { e.stopPropagation(); moveSection(section.id, 'down'); }}
              >
                ↓
              </button>
              <button
                className="text-red-400 hover:text-red-600"
                onClick={(e) => { e.stopPropagation(); removeSection(section.id); }}
              >
                ×
              </button>
            </div>
          ))}
        </div>

        <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">Add Section</h3>
        <div className="space-y-1">
          {SECTION_TYPES.map((st) => (
            <button
              key={st.value}
              className="w-full text-left px-2 py-1.5 text-sm rounded bg-gray-50 dark:bg-gray-800 hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
              onClick={() => addSection(st.value)}
            >
              + {st.label}
            </button>
          ))}
        </div>
      </div>

      {/* Center: Section editor */}
      <div className="flex-1 p-6 overflow-y-auto">
        <div className="max-w-2xl space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Template Name</label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Type</label>
              <select
                value={type}
                onChange={(e) => setType(e.target.value as TemplateType)}
                className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100"
              >
                {TEMPLATE_TYPES.map((t) => (
                  <option key={t.value} value={t.value}>{t.label}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Company Name</label>
              <input
                type="text"
                value={style.companyName}
                onChange={(e) => setStyle((s) => ({ ...s, companyName: e.target.value }))}
                className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100"
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Description</label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={2}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Primary Color</label>
              <input
                type="color"
                value={style.primaryColor}
                onChange={(e) => setStyle((s) => ({ ...s, primaryColor: e.target.value }))}
                className="w-full h-10 border border-gray-300 dark:border-gray-600 rounded-md"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Secondary Color</label>
              <input
                type="color"
                value={style.secondaryColor}
                onChange={(e) => setStyle((s) => ({ ...s, secondaryColor: e.target.value }))}
                className="w-full h-10 border border-gray-300 dark:border-gray-600 rounded-md"
              />
            </div>
          </div>

          {/* Active section editor */}
          {active && (
            <div className="border border-gray-200 dark:border-gray-700 rounded-lg p-4 mt-4">
              <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3">
                Edit: {active.type.replace(/_/g, ' ')}
              </h4>
              <div>
                <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Section Title</label>
                <input
                  type="text"
                  value={active.title}
                  onChange={(e) => updateSectionTitle(active.id, e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 text-sm"
                />
              </div>
              {active.type === 'table' && (
                <p className="mt-2 text-xs text-gray-500">
                  Configure table headers and rows in the template JSON or use the report builder for dynamic data binding.
                </p>
              )}
              {active.type === 'kpi_summary' && (
                <p className="mt-2 text-xs text-gray-500">
                  KPI cards are auto-populated from the data context. Customize labels in the template JSON.
                </p>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Right: Actions */}
      <div className="w-48 border-l border-gray-200 dark:border-gray-700 p-4 flex flex-col gap-2">
        <button
          onClick={handleSave}
          className="w-full px-3 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 text-sm font-medium"
        >
          Save Template
        </button>
        <button
          onClick={onCancel}
          className="w-full px-3 py-2 bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 rounded-md hover:bg-gray-200 dark:hover:bg-gray-700 text-sm"
        >
          Cancel
        </button>
        <div className="mt-4 text-xs text-gray-500 dark:text-gray-400">
          <p className="font-medium mb-1">Variables:</p>
          <p>{'{entity}'} — Company name</p>
          <p>{'{period}'} — Reporting period</p>
          <p>{'{currency}'} — Currency code</p>
          <p>{'{date}'} — Current date</p>
          <p>{'{preparedBy}'} — Author name</p>
        </div>
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { cn } from '@/utils/cn';
import { Button } from './Button';
import { Card, CardContent, CardHeader, CardTitle } from './Card';
import { Input } from './Input';
import type { ApprovalRequest, ApprovalState, ApprovalEvent } from '@/engines/WorkflowEngine';

interface Props {
  requests: ApprovalRequest[];
  onApprove: (id: string, comment?: string) => void;
  onReject: (id: string, comment?: string) => void;
  onBulkApprove: (ids: string[]) => void;
  currentUser: string;
  className?: string;
}

const STATE_BADGES: Record<ApprovalState, string> = {
  draft: 'bg-gray-100 text-gray-700',
  submitted: 'bg-blue-100 text-blue-700',
  in_review: 'bg-yellow-100 text-yellow-700',
  approved: 'bg-green-100 text-green-700',
  rejected: 'bg-red-100 text-red-700',
  locked: 'bg-purple-100 text-purple-700',
};

export function ApprovalQueue({
  requests,
  onApprove,
  onReject,
  onBulkApprove,
  currentUser: _currentUser,
  className,
}: Props) {
  const [filterState, setFilterState] = useState<ApprovalState | 'all'>('all');
  const [filterDate, setFilterDate] = useState('');
  const [filterRequester, setFilterRequester] = useState('');
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [commentMap, setCommentMap] = useState<Record<string, string>>({});
  const [showHistory, setShowHistory] = useState<string | null>(null);

  const filtered = useMemo(() => {
    return requests.filter((r) => {
      if (filterState !== 'all' && r.state !== filterState) return false;
      if (filterDate && !r.createdAt.startsWith(filterDate)) return false;
      if (filterRequester && !r.requester.toLowerCase().includes(filterRequester.toLowerCase()))
        return false;
      return true;
    });
  }, [requests, filterState, filterDate, filterRequester]);

  const toggleSelect = (id: string) => {
    const next = new Set(selected);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelected(next);
  };

  const toggleAll = () => {
    if (selected.size === filtered.length) {
      setSelected(new Set());
    } else {
      setSelected(new Set(filtered.map((r) => r.id)));
    }
  };

  const pending = filtered.filter((r) => ['submitted', 'in_review'].includes(r.state));
  const showBulk = pending.length > 0 && selected.size > 0;

  return (
    <Card className={cn('w-full', className)}>
      <CardHeader>
        <CardTitle className="flex items-center justify-between">
          <span>Approval Queue</span>
          {showBulk && (
            <Button
              size="sm"
              onClick={() => {
                onBulkApprove(Array.from(selected));
                setSelected(new Set());
              }}
            >
              Bulk Approve ({selected.size})
            </Button>
          )}
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Filters */}
        <div className="grid grid-cols-3 gap-3">
          <div>
            <label className="text-xs font-medium">Status</label>
            <select
              value={filterState}
              onChange={(e) => setFilterState(e.target.value as ApprovalState | 'all')}
              className="w-full border rounded px-2 py-1 text-sm"
            >
              <option value="all">All</option>
              <option value="submitted">Submitted</option>
              <option value="in_review">In Review</option>
              <option value="approved">Approved</option>
              <option value="rejected">Rejected</option>
              <option value="locked">Locked</option>
            </select>
          </div>
          <div>
            <label className="text-xs font-medium">Date</label>
            <Input type="date" value={filterDate} onChange={(e) => setFilterDate(e.target.value)} />
          </div>
          <div>
            <label className="text-xs font-medium">Requester</label>
            <Input
              value={filterRequester}
              onChange={(e) => setFilterRequester(e.target.value)}
              placeholder="Search..."
            />
          </div>
        </div>

        {/* Select All */}
        {pending.length > 0 && (
          <label className="flex items-center gap-2 text-sm">
            <input
              type="checkbox"
              checked={selected.size === filtered.length && filtered.length > 0}
              onChange={toggleAll}
            />
            Select all pending
          </label>
        )}

        {/* Request List */}
        <div className="space-y-2 max-h-96 overflow-y-auto">
          {filtered.map((req) => (
            <div key={req.id} className="border rounded-lg p-3 space-y-2">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  {['submitted', 'in_review'].includes(req.state) && (
                    <input
                      type="checkbox"
                      checked={selected.has(req.id)}
                      onChange={() => toggleSelect(req.id)}
                    />
                  )}
                  <span className="font-medium">{req.title}</span>
                  <span className={cn('text-xs px-2 py-0.5 rounded-full', STATE_BADGES[req.state])}>
                    {req.state.replace('_', ' ')}
                  </span>
                </div>
                <div className="flex gap-1 text-xs text-gray-500">
                  <span>{req.requester}</span>
                  <span>&middot;</span>
                  <span>{new Date(req.createdAt).toLocaleDateString()}</span>
                </div>
              </div>

              {req.description && <p className="text-sm text-gray-600">{req.description}</p>}

              {req.amount !== undefined && (
                <p className="text-sm font-medium">Amount: ${req.amount.toLocaleString()}</p>
              )}

              {/* Actions for pending */}
              {['submitted', 'in_review'].includes(req.state) && (
                <div className="flex items-center gap-2">
                  <Input
                    size={200}
                    value={commentMap[req.id] ?? ''}
                    onChange={(e) => setCommentMap({ ...commentMap, [req.id]: e.target.value })}
                    placeholder="Comment (optional)"
                    className="flex-1"
                  />
                  <Button
                    size="sm"
                    onClick={() => {
                      onApprove(req.id, commentMap[req.id]);
                      setCommentMap({ ...commentMap, [req.id]: '' });
                    }}
                  >
                    Approve
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => {
                      onReject(req.id, commentMap[req.id]);
                      setCommentMap({ ...commentMap, [req.id]: '' });
                    }}
                  >
                    Reject
                  </Button>
                </div>
              )}

              {/* History Toggle */}
              <button
                onClick={() => setShowHistory(showHistory === req.id ? null : req.id)}
                className="text-xs text-blue-500 hover:text-blue-700"
              >
                {showHistory === req.id ? 'Hide' : 'Show'} History ({req.history.length} events)
              </button>

              {showHistory === req.id && (
                <div className="pl-4 border-l-2 border-gray-200 space-y-1">
                  {req.history.map((evt: ApprovalEvent) => (
                    <div key={evt.id} className="text-xs text-gray-600">
                      <span className="font-medium">{evt.actor}</span>
                      <span className="mx-1">&middot;</span>
                      <span>{evt.action}</span>
                      {evt.comment && <span className="ml-1 text-gray-400">- {evt.comment}</span>}
                      <span className="ml-1 text-gray-400">
                        {new Date(evt.timestamp).toLocaleString()}
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}

          {filtered.length === 0 && (
            <div className="text-center py-8 text-gray-400">
              <p>No requests match your filters.</p>
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

import { useState } from 'react';
import { cn } from '@/utils/cn';
import { Button } from './Button';
import { Card, CardContent, CardHeader, CardTitle } from './Card';
import { Input } from './Input';
import type { WorkflowDefinition, WorkflowStep, StepType } from '@/engines/WorkflowEngine';

interface Props {
  onSave: (workflow: WorkflowDefinition) => void;
  initial?: WorkflowDefinition;
  className?: string;
}

export function ApprovalWorkflowDesigner({ onSave, initial, className }: Props) {
  const [name, setName] = useState(initial?.name ?? '');
  const [description, setDescription] = useState(initial?.description ?? '');
  const [steps, setSteps] = useState<WorkflowStep[]>(initial?.steps ?? []);
  const [editingStep, setEditingStep] = useState<number | null>(null);

  const addStep = () => {
    const step: WorkflowStep = {
      id: 'step-' + Date.now(),
      name: 'Step ' + (steps.length + 1),
      type: 'sequential',
      approvers: [],
      order: steps.length,
    };
    setSteps([...steps, step]);
    setEditingStep(steps.length);
  };

  const removeStep = (index: number) => {
    setSteps(steps.filter((_, i) => i !== index));
    if (editingStep === index) setEditingStep(null);
  };

  const moveStep = (index: number, dir: -1 | 1) => {
    const newIndex = index + dir;
    if (newIndex < 0 || newIndex >= steps.length) return;
    const newSteps = [...steps];
    [newSteps[index], newSteps[newIndex]] = [newSteps[newIndex], newSteps[index]];
    setSteps(newSteps.map((s, i) => ({ ...s, order: i })));
  };

  const updateStep = (index: number, updates: Partial<WorkflowStep>) => {
    setSteps(steps.map((s, i) => (i === index ? { ...s, ...updates } : s)));
  };

  const handleSave = () => {
    if (!name || steps.length === 0) return;
    onSave({
      id: initial?.id ?? '',
      name,
      description,
      steps,
      createdBy: initial?.createdBy ?? 'user',
      createdAt: initial?.createdAt ?? '',
      isTemplate: false,
    });
  };

  return (
    <Card className={cn('w-full', className)}>
      <CardHeader>
        <CardTitle>Workflow Designer</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="text-sm font-medium">Name</label>
            <Input
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Budget Approval"
            />
          </div>
          <div>
            <label className="text-sm font-medium">Description</label>
            <Input
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Approval workflow"
            />
          </div>
        </div>

        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-semibold">Steps</h3>
            <Button size="sm" onClick={addStep}>
              + Add Step
            </Button>
          </div>

          {steps.map((step, idx) => (
            <div
              key={step.id}
              className={cn(
                'border rounded-lg p-3',
                editingStep === idx
                  ? 'border-blue-500 bg-blue-50 dark:bg-blue-950'
                  : 'border-gray-200'
              )}
            >
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <span className="w-6 h-6 rounded-full bg-blue-500 text-white text-xs flex items-center justify-center">
                    {idx + 1}
                  </span>
                  <span className="font-medium">{step.name}</span>
                  <span className="text-xs text-gray-500">({step.type})</span>
                </div>
                <div className="flex gap-1">
                  <button
                    onClick={() => moveStep(idx, -1)}
                    disabled={idx === 0}
                    className="text-gray-400 hover:text-gray-600 disabled:opacity-30"
                  >
                    &#8593;
                  </button>
                  <button
                    onClick={() => moveStep(idx, 1)}
                    disabled={idx === steps.length - 1}
                    className="text-gray-400 hover:text-gray-600 disabled:opacity-30"
                  >
                    &#8595;
                  </button>
                  <button
                    onClick={() => setEditingStep(editingStep === idx ? null : idx)}
                    className="text-blue-500 hover:text-blue-700"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => removeStep(idx)}
                    className="text-red-500 hover:text-red-700"
                  >
                    &times;
                  </button>
                </div>
              </div>

              {editingStep === idx && (
                <div className="mt-3 space-y-3">
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="text-xs font-medium">Step Name</label>
                      <Input
                        value={step.name}
                        onChange={(e) => updateStep(idx, { name: e.target.value })}
                      />
                    </div>
                    <div>
                      <label className="text-xs font-medium">Type</label>
                      <select
                        value={step.type}
                        onChange={(e) => updateStep(idx, { type: e.target.value as StepType })}
                        className="w-full border rounded px-2 py-1 text-sm"
                      >
                        <option value="sequential">Sequential</option>
                        <option value="parallel">Parallel (all must approve)</option>
                      </select>
                    </div>
                  </div>

                  <div>
                    <label className="text-xs font-medium">Approvers (comma-separated)</label>
                    <Input
                      value={step.approvers.join(', ')}
                      onChange={(e) =>
                        updateStep(idx, {
                          approvers: e.target.value
                            .split(',')
                            .map((s) => s.trim())
                            .filter(Boolean),
                        })
                      }
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="text-xs font-medium">Timeout (hours, optional)</label>
                      <Input
                        type="number"
                        value={step.timeoutHours ?? ''}
                        onChange={(e) =>
                          updateStep(idx, {
                            timeoutHours: e.target.value ? Number(e.target.value) : undefined,
                          })
                        }
                      />
                    </div>
                    <div>
                      <label className="text-xs font-medium">Amount Threshold</label>
                      <Input
                        type="number"
                        value={step.condition?.value ?? ''}
                        onChange={(e) =>
                          updateStep(idx, {
                            condition: e.target.value
                              ? { field: 'amount', operator: 'gt', value: Number(e.target.value) }
                              : undefined,
                          })
                        }
                        placeholder="> $10,000 needs VP"
                      />
                    </div>
                  </div>
                </div>
              )}
            </div>
          ))}

          {steps.length === 0 && (
            <div className="text-center py-8 text-gray-400">
              <p>No steps added yet.</p>
              <p className="text-sm">Click &quot;+ Add Step&quot; to begin.</p>
            </div>
          )}
        </div>

        <div className="flex justify-end gap-2">
          <Button
            variant="outline"
            onClick={() => {
              setSteps([]);
              setName('');
              setDescription('');
            }}
          >
            Reset
          </Button>
          <Button onClick={handleSave} disabled={!name || steps.length === 0}>
            Save Workflow
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState, useCallback } from 'react';
import { cn } from '@/utils/cn';
import { Modal } from './Modal';
import { Button } from './Button';
import { Input } from './Input';
import { Select } from './Select';

export type NumberFormat =
  | 'general'
  | 'number'
  | 'currency'
  | 'percent'
  | 'date'
  | 'scientific'
  | 'text';

export interface CellFormat {
  format: NumberFormat;
  decimals: number;
  useThousandsSeparator: boolean;
  currencySymbol: string;
  dateFormat: string;
  prefix: string;
  suffix: string;
  negativeStyle: 'minus' | 'parentheses' | 'red';
}

export interface CellFormatterProps {
  isOpen: boolean;
  onClose: () => void;
  onApply: (format: CellFormat) => void;
  currentFormat?: CellFormat;
  className?: string;
}

const defaultFormat: CellFormat = {
  format: 'general',
  decimals: 2,
  useThousandsSeparator: true,
  currencySymbol: '$',
  dateFormat: 'MM/DD/YYYY',
  prefix: '',
  suffix: '',
  negativeStyle: 'minus',
};

const formatOptions = [
  { value: 'general', label: 'General' },
  { value: 'number', label: 'Number' },
  { value: 'currency', label: 'Currency' },
  { value: 'percent', label: 'Percentage' },
  { value: 'date', label: 'Date' },
  { value: 'scientific', label: 'Scientific' },
  { value: 'text', label: 'Text' },
];

const currencyOptions = [
  { value: '$', label: '$ USD' },
  { value: '€', label: '€ EUR' },
  { value: '£', label: '£ GBP' },
  { value: '¥', label: '¥ JPY' },
  { value: '₹', label: '₹ INR' },
  { value: 'A$', label: 'A$ AUD' },
  { value: 'C$', label: 'C$ CAD' },
  { value: 'CHF', label: 'CHF' },
];

const dateFormatOptions = [
  { value: 'MM/DD/YYYY', label: '12/31/2026' },
  { value: 'DD/MM/YYYY', label: '31/12/2026' },
  { value: 'YYYY-MM-DD', label: '2026-12-31' },
  { value: 'MMM DD, YYYY', label: 'Dec 31, 2026' },
  { value: 'DD MMM YYYY', label: '31 Dec 2026' },
  { value: 'MMMM DD, YYYY', label: 'December 31, 2026' },
];

const negativeStyleOptions = [
  { value: 'minus', label: '-1,234.56' },
  { value: 'parentheses', label: '(1,234.56)' },
  { value: 'red', label: '1,234.56 (red)' },
];

function formatPreview(format: CellFormat): string {
  const sample = 1234.56;
  const negSample = -1234.56;

  switch (format.format) {
    case 'general':
      return sample.toLocaleString();
    case 'number': {
      const opts: Intl.NumberFormatOptions = {
        minimumFractionDigits: format.decimals,
        maximumFractionDigits: format.decimals,
        useGrouping: format.useThousandsSeparator,
      };
      const formatted = sample.toLocaleString('en-US', opts);
      const negFormatted = negSample.toLocaleString('en-US', opts);
      if (format.negativeStyle === 'parentheses') return `(${negFormatted.replace('-', '')})`;
      return formatted;
    }
    case 'currency': {
      const opts: Intl.NumberFormatOptions = {
        style: 'currency',
        currency: 'USD',
        minimumFractionDigits: format.decimals,
        maximumFractionDigits: format.decimals,
      };
      return sample.toLocaleString('en-US', opts).replace('$', format.currencySymbol);
    }
    case 'percent':
      return `${(sample * 100).toFixed(format.decimals)}%`;
    case 'date':
      return '12/31/2026';
    case 'scientific':
      return sample.toExponential(format.decimals);
    case 'text':
      return String(sample);
    default:
      return String(sample);
  }
}

export function CellFormatter({
  isOpen,
  onClose,
  onApply,
  currentFormat,
  className,
}: CellFormatterProps) {
  const [format, setFormat] = useState<CellFormat>(currentFormat || defaultFormat);

  const updateFormat = useCallback(<K extends keyof CellFormat>(key: K, value: CellFormat[K]) => {
    setFormat((prev) => ({ ...prev, [key]: value }));
  }, []);

  const handleApply = useCallback(() => {
    onApply(format);
    onClose();
  }, [format, onApply, onClose]);

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="Format Cells"
      className={cn('max-w-md', className)}
    >
      <div className="space-y-4 p-4">
        {/* Format Type */}
        <div>
          <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1.5 uppercase tracking-wide">
            Category
          </label>
          <Select
            options={formatOptions}
            value={format.format}
            onValueChange={(v) => updateFormat('format', v as NumberFormat)}
          />
        </div>

        {/* Number options */}
        {(format.format === 'number' ||
          format.format === 'currency' ||
          format.format === 'percent' ||
          format.format === 'scientific') && (
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1.5 uppercase tracking-wide">
                Decimal Places
              </label>
              <Input
                type="number"
                min={0}
                max={15}
                value={format.decimals}
                onChange={(e) => updateFormat('decimals', parseInt(e.target.value) || 0)}
              />
            </div>
            <div className="flex items-end">
              <label className="flex items-center gap-2 text-xs cursor-pointer">
                <input
                  type="checkbox"
                  checked={format.useThousandsSeparator}
                  onChange={(e) => updateFormat('useThousandsSeparator', e.target.checked)}
                  className="rounded border-gray-300"
                  aria-label="Use thousands separator"
                />
                Thousands separator
              </label>
            </div>
          </div>
        )}

        {/* Currency symbol */}
        {format.format === 'currency' && (
          <div>
            <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1.5 uppercase tracking-wide">
              Symbol
            </label>
            <Select
              options={currencyOptions}
              value={format.currencySymbol}
              onValueChange={(v) => updateFormat('currencySymbol', v)}
            />
          </div>
        )}

        {/* Date format */}
        {format.format === 'date' && (
          <div>
            <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1.5 uppercase tracking-wide">
              Date Format
            </label>
            <Select
              options={dateFormatOptions}
              value={format.dateFormat}
              onValueChange={(v) => updateFormat('dateFormat', v)}
            />
          </div>
        )}

        {/* Negative style */}
        {(format.format === 'number' || format.format === 'currency') && (
          <div>
            <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1.5 uppercase tracking-wide">
              Negative Numbers
            </label>
            <Select
              options={negativeStyleOptions}
              value={format.negativeStyle}
              onValueChange={(v) => updateFormat('negativeStyle', v as CellFormat['negativeStyle'])}
            />
          </div>
        )}

        {/* Prefix/Suffix */}
        {format.format !== 'date' && format.format !== 'text' && (
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1.5 uppercase tracking-wide">
                Prefix
              </label>
              <Input
                value={format.prefix}
                onChange={(e) => updateFormat('prefix', e.target.value)}
                placeholder="e.g., ~"
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-[var(--text-secondary)] mb-1.5 uppercase tracking-wide">
                Suffix
              </label>
              <Input
                value={format.suffix}
                onChange={(e) => updateFormat('suffix', e.target.value)}
                placeholder="e.g., units"
              />
            </div>
          </div>
        )}

        {/* Preview */}
        <div
          className="bg-gray-50 rounded-md p-3 border border-gray-200"
          role="status"
          aria-live="polite"
          aria-label="Format preview"
        >
          <div className="text-[10px] font-semibold text-gray-400 uppercase tracking-wider mb-1">
            Sample
          </div>
          <div className="text-lg font-mono text-[var(--text-primary)] tabular-nums">
            {format.prefix}
            {formatPreview(format)}
            {format.suffix}
          </div>
        </div>

        {/* Actions */}
        <div className="flex justify-end gap-2 pt-2">
          <Button variant="outline" onClick={onClose}>
            Cancel
          </Button>
          <Button onClick={handleApply}>Apply</Button>
        </div>
      </div>
    </Modal>
  );
}

