  });

  it('shows category headers', () => {
    render(<CommandPalette items={items} isOpen={true} onClose={vi.fn()} />);
    expect(screen.getByText('File')).toBeInTheDocument();
    expect(screen.getByText('Reports')).toBeInTheDocument();
