    const engine2 = new DataGovernanceEngine();
    engine2.deserialize(json);
    expect(engine2.getAsset('a1')?.name).toBe('Test');
  });

  it('should get stats', () => {
    engine.addAsset({
      id: 'a1',
      name: 'A',
      type: 'table',
      source: 'GL',
      owner: 'CFO',
      sensitivity: 'public',
      tags: [],
