      expect(FormulaFunctionRegistry.CLAMP(15, 1, 10)).toBe(10);
    });

    it('COALESCE: first non-zero', () => {
      expect(FormulaFunctionRegistry.COALESCE(0, 0, 5, 10)).toBe(5);
    });

    it('COALESCE: all zero', () => {
      expect(FormulaFunctionRegistry.COALESCE(0, 0, 0)).toBe(0);
    });
  });

  // =========================================================================
  // CHAOS ENGINEERING: NaN Poisoning, Division by Zero, String Coercion
  // =========================================================================

  describe('chaos: NaN poisoning resistance', () => {
    it('SUM with variadic args skips NaN', () => {
      expect(FormulaFunctionRegistry.SUM(1, NaN, 3)).toBe(4);
      expect(FormulaFunctionRegistry.SUM(NaN, NaN, NaN)).toBe(0);
      expect(FormulaFunctionRegistry.SUM(10, NaN, 20, NaN, 30)).toBe(60);
    });

    it('SUM with nested arrays skips NaN', () => {
      expect(FormulaFunctionRegistry.SUM([1, NaN], [3, NaN], [5])).toBe(9);
    });

    it('SUM coerces numeric strings', () => {
      expect(FormulaFunctionRegistry.SUM('5', 3)).toBe(8);
      expect(FormulaFunctionRegistry.SUM(['10', '20', 30])).toBe(60);
      expect(FormulaFunctionRegistry.SUM('hello', 5)).toBe(5); // non-numeric string skipped
    });

    it('COUNT counts only valid numbers, not NaN', () => {
      expect(FormulaFunctionRegistry.COUNT(1, NaN, 3)).toBe(2);
      expect(FormulaFunctionRegistry.COUNT([NaN, NaN, NaN])).toBe(0);
      expect(FormulaFunctionRegistry.COUNT('5', 10, NaN)).toBe(2);
    });

    it('AVERAGE with variadic args skips NaN', () => {
      expect(FormulaFunctionRegistry.AVERAGE(10, NaN, 30)).toBe(20);
      expect(FormulaFunctionRegistry.AVERAGE(NaN, NaN)).toBe(0);
    });

    it('MEDIAN with variadic args skips NaN', () => {
      expect(FormulaFunctionRegistry.MEDIAN(1, NaN, 3, 5)).toBe(3);
      expect(FormulaFunctionRegistry.MEDIAN(NaN, 2, NaN, 4, NaN)).toBe(3);
      expect(FormulaFunctionRegistry.MEDIAN(NaN, NaN)).toBe(0);
    });

    it('STDEV with NaN does not produce NaN', () => {
      const result = FormulaFunctionRegistry.STDEV(2, NaN, 4, 4, 5, 5, 7, 9);
      expect(result).not.toBeNaN();
      expect(result).toBeCloseTo(FormulaFunctionRegistry.STDEV([2, 4, 4, 5, 5, 7, 9]), 5);
    });

    it('VARIANCE with NaN does not produce NaN', () => {
      const result = FormulaFunctionRegistry.VARIANCE(NaN, 2, 4, NaN, 4, 5);
      expect(result).not.toBeNaN();
    });

    it('STDEVP with NaN does not produce NaN', () => {
      const result = FormulaFunctionRegistry.STDEVP(NaN, 1, 2, 3, NaN);
      expect(result).not.toBeNaN();
    });

    it('VARP with NaN does not produce NaN', () => {
      const result = FormulaFunctionRegistry.VARP(NaN, 1, 2, 3, NaN);
      expect(result).not.toBeNaN();
    });

    it('CORREL with NaN pairs filters them out', () => {
      const result = FormulaFunctionRegistry.CORREL([1, NaN, 3], [4, 5, 6]);
      expect(result).not.toBeNaN();
    });

    it('MODE with NaN skips NaN', () => {
      expect(FormulaFunctionRegistry.MODE(NaN, 1, 1, 2, NaN)).toBe(1);
    });

    it('GEOMEAN with NaN skips NaN', () => {
      expect(FormulaFunctionRegistry.GEOMEAN(NaN, 4, 16)).toBeCloseTo(8, 10);
    });

    it('HARMEAN with NaN skips NaN', () => {
      expect(FormulaFunctionRegistry.HARMEAN(NaN, 1, 4)).toBeCloseTo(1.6, 1);
    });
  });

  describe('chaos: division by zero', () => {
    it('MOD by zero returns NaN (not 0 or Infinity)', () => {
      const result = FormulaFunctionRegistry.MOD(10, 0);
      expect(result).toBeNaN();
    });

    it('MOD(0, 0) returns NaN', () => {
      const result = FormulaFunctionRegistry.MOD(0, 0);
      expect(result).toBeNaN();
    });

    it('MOD normal case still works', () => {
      expect(FormulaFunctionRegistry.MOD(10, 3)).toBe(1);
      expect(FormulaFunctionRegistry.MOD(7, 2)).toBe(1);
    });
  });

  describe('chaos: string coercion consistency', () => {
    it('SUM coerces numeric strings to numbers', () => {
      expect(FormulaFunctionRegistry.SUM('10', '20', '30')).toBe(60);
      expect(FormulaFunctionRegistry.SUM(['5', 10, '15'])).toBe(30);
    });

    it('SUM skips non-numeric strings', () => {
      expect(FormulaFunctionRegistry.SUM('hello', 'world', 5)).toBe(5);
      expect(FormulaFunctionRegistry.SUM('', 10)).toBe(10);
    });

    it('COUNT counts numeric strings as valid', () => {
      expect(FormulaFunctionRegistry.COUNT('5', '10', NaN)).toBe(2);
    });

    it('AVERAGE coerces numeric strings', () => {
      expect(FormulaFunctionRegistry.AVERAGE('10', '20', '30')).toBe(20);
    });

    it('MIN/MAX coerce numeric strings', () => {
      expect(FormulaFunctionRegistry.MIN('3', 1, '5')).toBe(1);
      expect(FormulaFunctionRegistry.MAX('3', 1, '5')).toBe(5);
    });
  });

  // =========================================================================
  // NaN POISONING FIXES (Chaos Engineer)
  // =========================================================================

  describe('NaN poisoning protection', () => {
    it('SUM skips NaN values like Excel', () => {
      expect(FormulaFunctionRegistry.SUM(1, NaN, 3)).toBe(4);
      expect(FormulaFunctionRegistry.SUM(NaN, NaN, NaN)).toBe(0);
      expect(FormulaFunctionRegistry.SUM([10, NaN, 20, NaN, 30])).toBe(60);
      expect(FormulaFunctionRegistry.SUM(NaN)).toBe(0);
      expect(FormulaFunctionRegistry.SUM(1, 2, 3)).toBe(6);
    });

    it('AVERAGE skips NaN values', () => {
      expect(FormulaFunctionRegistry.AVERAGE(10, NaN, 30)).toBe(20);
      expect(FormulaFunctionRegistry.AVERAGE(NaN, NaN)).toBe(0);
      expect(FormulaFunctionRegistry.AVERAGE([5, NaN, 15])).toBe(10);
    });

    it('COUNT skips NaN values', () => {
      expect(FormulaFunctionRegistry.COUNT(1, NaN, 3)).toBe(2);
      expect(FormulaFunctionRegistry.COUNT(NaN, NaN)).toBe(0);
    });

    it('PRODUCT skips NaN values', () => {
      expect(FormulaFunctionRegistry.PRODUCT(2, NaN, 5)).toBe(10);
      expect(FormulaFunctionRegistry.PRODUCT(NaN, NaN)).toBe(0);
      expect(FormulaFunctionRegistry.PRODUCT(3, 4)).toBe(12);
    });

    it('MEDIAN skips NaN values', () => {
      expect(FormulaFunctionRegistry.MEDIAN(1, NaN, 3, 5)).toBe(3);
    });

    it('STDEV skips NaN values', () => {
      const result = FormulaFunctionRegistry.STDEV(10, NaN, 20, 30);
      expect(result).toBeGreaterThan(0);
      expect(isNaN(result)).toBe(false);
    });

    it('VARIANCE skips NaN values', () => {
      const result = FormulaFunctionRegistry.VARIANCE(10, NaN, 20, 30);
      expect(result).toBeGreaterThan(0);
      expect(isNaN(result)).toBe(false);
    });

    it('SUMIF skips NaN in sum range', () => {
      const range = [1, 2, 3, 2];
      const sumRange = [10, 20, NaN, 40];
      // Criteria: match values === 2 (indices 1 and 3)
      // sumRange[1]=20 + sumRange[3]=40, NaN at index 2 is skipped
      const result = FormulaFunctionRegistry.call('SUMIF', range, 2, sumRange);
      expect(result).toBe(60);
    });

    it('IMSUM skips NaN values', () => {
      const result = FormulaFunctionRegistry.call('IMSUM', 1, NaN, 3);
      expect(result).toBe(4);
    });

    it('IMPRODUCT skips NaN values', () => {
      const result = FormulaFunctionRegistry.call('IMPRODUCT', 2, NaN, 5);
      expect(result).toBe(10);
    });
  });

  // =========================================================================
  // DIVISION BY ZERO FIXES (Chaos Engineer)
  // =========================================================================

  describe('division by zero behavior', () => {
    it('DIVIDE returns Infinity for positive / 0', () => {
      expect(FormulaFunctionRegistry.call('DIVIDE', 10, 0)).toBe(Infinity);
    });

    it('DIVIDE returns -Infinity for negative / 0', () => {
      expect(FormulaFunctionRegistry.call('DIVIDE', -10, 0)).toBe(-Infinity);
    });

    it('DIVIDE returns NaN for 0 / 0', () => {
      expect(FormulaFunctionRegistry.call('DIVIDE', 0, 0)).toBeNaN();
    });

    it('DIVIDE returns correct result for normal division', () => {
      expect(FormulaFunctionRegistry.call('DIVIDE', 10, 2)).toBe(5);
      expect(FormulaFunctionRegistry.call('DIVIDE', -10, 2)).toBe(-5);
    });

    it('IMDIV returns Infinity for positive / 0', () => {
      expect(FormulaFunctionRegistry.call('IMDIV', 10, 0)).toBe(Infinity);
    });

    it('IMDIV returns -Infinity for negative / 0', () => {
      expect(FormulaFunctionRegistry.call('IMDIV', -10, 0)).toBe(-Infinity);
    });

    it('IMDIV returns NaN for 0 / 0', () => {
      expect(FormulaFunctionRegistry.call('IMDIV', 0, 0)).toBeNaN();
    });

    it('QUOTIENT returns Infinity for positive / 0', () => {
      expect(FormulaFunctionRegistry.call('QUOTIENT', 10, 0)).toBe(Infinity);
    });

    it('QUOTIENT returns NaN for 0 / 0', () => {
      expect(FormulaFunctionRegistry.call('QUOTIENT', 0, 0)).toBeNaN();
    });

    it('QUOTIENT returns correct integer division for normal cases', () => {
      expect(FormulaFunctionRegistry.call('QUOTIENT', 7, 2)).toBe(3);
      expect(FormulaFunctionRegistry.call('QUOTIENT', -7, 2)).toBe(-3);
    });
  });
});

