      expect(value).toBeUndefined();
    });

    it('should get modified cells', () => {
      const sandbox = engine.createSandbox('Test', undefined, 'snap-1', baseCells);
      engine.applyModification(
        sandbox.id,
        'Budget',
        { Account: 'Account:Revenue', Scenario: 'Scenario:Budget' },
