  mockListen: vi.fn(),
  mockUnlisten: vi.fn(),
  mockRegister: vi.fn(),
}));

vi.mock('react-router-dom', () => ({
  useNavigate: () => mockNavigate,
}));

vi.mock('@tauri-apps/api/event', () => ({
  listen: (...args: any[]) => {
