    const cogs = entries
      .filter((e) => (e.accountCode || '').startsWith('5'))
      .reduce((s, e) => s + Math.abs(e.debit - e.credit), 0);
    const expenses = entries
      .filter((e) => (e.accountCode || '').startsWith('6'))
      .reduce((s, e) => s + Math.abs(e.debit - e.credit), 0);
    const assets =
      Math.abs(
        entries
          .filter((e) => (e.accountCode || '').startsWith('1'))
          .reduce((s, e) => s + (e.debit - e.credit), 0)
      ) || 1;
    const liabilities =
      Math.abs(
        entries
          .filter((e) => (e.accountCode || '').startsWith('2'))
          .reduce((s, e) => s + (e.credit - e.debit), 0)
      ) || 1;
    const equity =
      Math.abs(
        entries
          .filter((e) => (e.accountCode || '').startsWith('3'))
          .reduce((s, e) => s + (e.credit - e.debit), 0)
      ) || 1;
    const currentAssets =
      Math.abs(
        entries
          .filter((e) => (e.accountCode || '').startsWith('11'))
          .reduce((s, e) => s + (e.debit - e.credit), 0)
      ) || 1;
    const currentLiabs =
      Math.abs(
        entries
          .filter((e) => (e.accountCode || '').startsWith('21'))
          .reduce((s, e) => s + (e.credit - e.debit), 0)
      ) || 1;
    const netIncome = revenue - cogs - expenses;
    return {
      current: currentAssets / currentLiabs,
      quick: (currentAssets - 0) / currentLiabs,
      'debt-to-equity': liabilities / equity,
      'gross-margin': revenue > 0 ? ((revenue - cogs) / revenue) * 100 : 0,
      'net-margin': revenue > 0 ? (netIncome / revenue) * 100 : 0,
      roa: assets > 0 ? (netIncome / assets) * 100 : 0,
      roe: equity > 0 ? (netIncome / equity) * 100 : 0,
      'asset-turnover': assets > 0 ? revenue / assets : 0,
    };
  }, [entries]);

  if (entries.length === 0)
    return (
      <div className="p-12 text-center">
        <BarChart3 className="h-10 w-10 text-slate-400 mx-auto mb-4" />
        <h2 className="text-xl font-semibold mb-2">No Data</h2>
        <p className="text-slate-400 mb-6">Import GL data to calculate benchmarks.</p>
        <Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>
      </div>
    );
  if (!ratios)
    return (
      <div className="p-6">
        <Skeleton count={8} height={48} />
      </div>
    );

  return (
    <div className="p-6 space-y-6">
      <h1 className="text-2xl font-bold">Benchmarking</h1>
      <p className="text-sm text-slate-400">8 key financial ratios computed from your GL data</p>
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        {RATIOS.map((r) => {
          const val = ratios[r.id as keyof typeof ratios];
          const formatted = r.type === 'percent' ? val.toFixed(1) + '%' : val.toFixed(2);
          return (
            <Card key={r.id}>
              <CardContent className="p-4">
                <div className="text-xs text-slate-400 mb-1">{r.label}</div>
                <div className="text-2xl font-bold tabular-nums">{formatted}</div>
                <div className="text-[10px] text-slate-500 mt-1">{r.formula}</div>
              </CardContent>
            </Card>
          );
        })}
      </div>
    </div>
  );
}

﻿import { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useGLStore } from '@/store/glStore';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Card, CardContent } from '@/components/ui/Card';
import { Skeleton } from '@/components/ui/Skeleton';
import { Target } from 'lucide-react';

interface BreakevenResult {
  type: 'breakeven';
  breakevenRevenue: number;
  revenueForTarget: number;
  contributionMargin: number;
  fixedCost: number;
  variableCostPct: number;
}

interface MonteCarloResult {
  type: 'montecarlo';
  simulations: Array<{ revenue: number; costs: number; profit: number }>;
  avgProfit: number;
  median: number;
  p10: number;
  p90: number;
  positivePct: number;
  count: number;
}

type GoalSeekResults = BreakevenResult | MonteCarloResult | null;

function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
  }).format(n);
}

export default function GoalSeekPage() {
  const { entries } = useGLStore();
  const navigate = useNavigate();
  const [mode, setMode] = useState<'goalseek' | 'montecarlo' | 'breakeven'>('breakeven');
  const [targetProfit, setTargetProfit] = useState(1000000);
  const [fixedCost, setFixedCost] = useState(500000);
  const [variableCostPct, setVariableCostPct] = useState(60);
  const [iterations, setIterations] = useState(1000);
  const [results, setResults] = useState<GoalSeekResults>(null);
  const [loading, setLoading] = useState(false);

  const actuals = useMemo(() => {
    if (entries.length === 0) return null;
    const revenue = entries
      .filter((e) => (e.accountCode || '').startsWith('4'))
      .reduce((s, e) => s + (e.debit - e.credit), 0);
    const expenses = entries
      .filter((e) => (e.accountCode || '').startsWith('5') || (e.accountCode || '').startsWith('6'))
      .reduce((s, e) => s + Math.abs(e.debit - e.credit), 0);
    return { revenue, expenses, netIncome: revenue - expenses };
  }, [entries]);

  const runBreakeven = () => {
    const contributionMargin = 100 - variableCostPct;
    const beRevenue = contributionMargin > 0 ? fixedCost / (contributionMargin / 100) : 0;
    const revForTarget =
      contributionMargin > 0 ? (fixedCost + targetProfit) / (contributionMargin / 100) : 0;
    setResults({
      type: 'breakeven',
      breakevenRevenue: beRevenue,
      revenueForTarget: revForTarget,
      contributionMargin,
      fixedCost,
      variableCostPct,
    });
  };

  const runMonteCarlo = () => {
    setLoading(true);
    setTimeout(() => {
      const sims = Array.from({ length: iterations }, () => {
        const revMultiplier = 0.8 + Math.random() * 0.4;
        const costMultiplier = 0.85 + Math.random() * 0.3;
        const base = actuals?.revenue || 1000000;
        const revenue = base * revMultiplier;
        const costs = (base * (variableCostPct / 100) + fixedCost) * costMultiplier;
        return { revenue, costs, profit: revenue - costs };
      });
      const profits = sims.map((s) => s.profit).sort((a, b) => a - b);
      const avgProfit = profits.reduce((s, p) => s + p, 0) / profits.length;
      const median = profits[Math.floor(profits.length / 2)];
      const p10 = profits[Math.floor(profits.length * 0.1)];
      const p90 = profits[Math.floor(profits.length * 0.9)];
      const positiveOutcomes = profits.filter((p) => p >= 0).length;
      setResults({
        type: 'montecarlo',
        simulations: sims,
        avgProfit,
        median,
        p10,
        p90,
        positivePct: (positiveOutcomes / iterations) * 100,
        count: iterations,
      });
      setLoading(false);
    }, 500);
  };

  if (!actuals && mode !== 'breakeven') {
    return (
      <div className="p-12 text-center">
        <Target className="h-10 w-10 text-slate-400 mx-auto mb-4" />
        <h2 className="text-xl font-semibold mb-2">No Data</h2>
        <p className="text-slate-400 mb-6">Import GL data for Monte Carlo simulations.</p>
        <Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <h1 className="text-2xl font-bold">Financial Modeling</h1>
      <div className="flex gap-2">
        {['breakeven', 'goalseek', 'montecarlo'].map((m) => (
          <button
            key={m}
            onClick={() => {
              setMode(m as typeof mode);
              setResults(null);
            }}
            className={
              'px-3 py-1.5 rounded text-xs font-medium ' +
              (mode === m ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400')
            }
          >
            {m === 'breakeven' ? 'Break-Even' : m === 'goalseek' ? 'Goal Seek' : 'Monte Carlo'}
          </button>
        ))}
      </div>

      {mode === 'breakeven' && (
        <Card>
          <CardContent className="p-4 space-y-4">
            <h3 className="font-semibold">Break-Even Analysis</h3>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Fixed Costs</label>
              <Input
                type="number"
                value={fixedCost}
                onChange={(e) => setFixedCost(parseFloat(e.target.value) || 0)}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">
                Variable Cost (% of Revenue)
              </label>
              <Input
                type="number"
                value={variableCostPct}
                onChange={(e) => setVariableCostPct(parseFloat(e.target.value) || 0)}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">
                Target Profit (for goal seek)
              </label>
              <Input
                type="number"
                value={targetProfit}
                onChange={(e) => setTargetProfit(parseFloat(e.target.value) || 0)}
              />
            </div>
            <Button onClick={runBreakeven}>Calculate</Button>
            {results && results.type === 'breakeven' && (
              <div className="space-y-2 text-sm pt-4 border-t border-slate-800">
                <div className="flex justify-between">
                  <span className="text-slate-400">Contribution Margin</span>
                  <span className="font-semibold">{results.contributionMargin.toFixed(1)}%</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-400">Break-Even Revenue</span>
                  <span className="font-semibold text-green-400">
                    {formatCurrency(results.breakevenRevenue)}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-400">Revenue for Target Profit</span>
                  <span className="font-semibold text-blue-400">
                    {formatCurrency(results.revenueForTarget)}
                  </span>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {mode === 'montecarlo' && (
        <Card>
          <CardContent className="p-4 space-y-4">
            <h3 className="font-semibold">Monte Carlo Simulation</h3>
            <p className="text-sm text-slate-400">
              Base revenue: {actuals ? formatCurrency(actuals.revenue) : '$1,000,000'}
            </p>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Iterations</label>
              <Input
                type="number"
                value={iterations}
                onChange={(e) => setIterations(parseInt(e.target.value) || 100)}
              />
            </div>
            <Button onClick={runMonteCarlo} disabled={loading}>
              {loading ? 'Running...' : 'Run Simulation'}
            </Button>
            {loading && <Skeleton variant="rectangular" height="100px" />}
            {results && results.type === 'montecarlo' && !loading && (
              <div className="space-y-2 text-sm pt-4 border-t border-slate-800">
                <div className="flex justify-between">
                  <span className="text-slate-400">Iterations</span>
                  <span>{results.count.toLocaleString()}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-400">Avg Profit</span>
                  <span className="font-semibold">{formatCurrency(results.avgProfit)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-400">Median</span>
                  <span className="font-semibold">{formatCurrency(results.median)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-400">P10 / P90</span>
                  <span>
                    {formatCurrency(results.p10)} / {formatCurrency(results.p90)}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-400">Positive Outcomes</span>
                  <span
                    className={
                      'font-semibold ' +
                      (results.positivePct > 50 ? 'text-green-400' : 'text-red-400')
                    }
                  >
                    {results.positivePct.toFixed(1)}%
                  </span>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      )}
    </div>
  );
}

﻿import { useEffect, useMemo, useState, useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { CellAuditTrailEngine } from '@/engines/CellAuditTrailEngine';
import { Button } from '@/components/ui/Button';
import { Card, CardContent } from '@/components/ui/Card';
import { ScrollText, Download, RefreshCw } from 'lucide-react';

function formatRelativeTime(timestamp: string): string {
  const diff = Date.now() - new Date(timestamp).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'Just now';
  if (mins < 60) return mins + 'm ago';
  const hours = Math.floor(mins / 60);
  if (hours < 24) return hours + 'h ago';
  return new Date(timestamp).toLocaleDateString();
}

export default function AuditTrailPage() {
  useEffect(() => {
    document.title = 'FinPlan Pro — Audit Trail';
  }, []);

  const navigate = useNavigate();
  const [entries, setEntries] = useState(() => CellAuditTrailEngine.getAllEntries());
  const [filters, setFilters] = useState({ startDate: '', endDate: '', user: '', action: '' });
  const [sortField] = useState<'timestamp' | 'user'>('timestamp');
  const [sortDir] = useState<'asc' | 'desc'>('desc');
  const intervalRef = useRef<ReturnType<typeof setInterval>>();

  // Auto-refresh every 5 seconds
  useEffect(() => {
    intervalRef.current = setInterval(() => {
      setEntries(CellAuditTrailEngine.getAllEntries());
    }, 5000);
    return () => clearInterval(intervalRef.current);
  }, []);

  const filtered = useMemo(() => {
    let list = [...entries];
    if (filters.startDate) list = list.filter((e) => e.timestamp >= filters.startDate);
    if (filters.endDate) list = list.filter((e) => e.timestamp <= filters.endDate + 'T23:59:59');
    if (filters.user)
      list = list.filter((e) => e.userName.toLowerCase().includes(filters.user.toLowerCase()));
    if (filters.action)
      list = list.filter((e) =>
        (e.reason || '').toLowerCase().includes(filters.action.toLowerCase())
      );
    list.sort((a, b) => {
      const cmp = a[sortField] < b[sortField] ? -1 : 1;
      return sortDir === 'asc' ? cmp : -cmp;
    });
    return list;
  }, [entries, filters, sortField, sortDir]);

  const handleExport = useCallback(() => {
    const headers = ['Timestamp', 'User', 'Account', 'Old Value', 'New Value', 'Reason'];
    const rows = filtered.map((e) => [
      e.timestamp,
      e.userName,
      e.accountName || e.accountId,
      e.oldValue?.toString() ?? '',
      e.newValue?.toString() ?? '',
      e.reason ?? '',
    ]);
    const csv = [headers.join(','), ...rows.map((r) => r.map((c) => `"${c}"`).join(','))].join(
      '\n'
    );
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `audit-trail-${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  }, [filtered]);

  if (entries.length === 0) {
    return (
      <div className="p-12 text-center max-w-md mx-auto">
        <div className="p-4 bg-slate-800 rounded-full inline-block mb-4">
          <ScrollText className="h-10 w-10 text-slate-400" />
        </div>
        <h2 className="text-xl font-semibold mb-2">No Audit Entries</h2>
        <p className="text-slate-400 mb-6">
          Changes appear automatically as you edit budgets, forecasts, and other data. Import data
          and make changes to see them recorded here.
        </p>
        <Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">Audit Trail</h1>
          <p className="text-sm text-slate-400 mt-1">{entries.length} total entries</p>
        </div>
        <div className="flex gap-2">
          <Button
            size="sm"
            variant="ghost"
            onClick={() => setEntries(CellAuditTrailEngine.getAllEntries())}
          >
            <RefreshCw className="h-3.5 w-3.5 mr-1.5" />
            Refresh
          </Button>
          <Button size="sm" variant="ghost" onClick={handleExport}>
            <Download className="h-3.5 w-3.5 mr-1.5" />
            Export
          </Button>
        </div>
      </div>

      <Card>
        <CardContent className="p-4">
          <div className="flex gap-3 items-end flex-wrap">
            <div>
              <label className="block text-xs text-slate-500 mb-1">From</label>
              <input
                type="date"
                className="bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm w-36"
                value={filters.startDate}
                onChange={(e) => setFilters((f) => ({ ...f, startDate: e.target.value }))}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-500 mb-1">To</label>
              <input
                type="date"
                className="bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm w-36"
                value={filters.endDate}
                onChange={(e) => setFilters((f) => ({ ...f, endDate: e.target.value }))}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-500 mb-1">User</label>
              <input
                className="bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm w-40"
                placeholder="Filter by user..."
                value={filters.user}
                onChange={(e) => setFilters((f) => ({ ...f, user: e.target.value }))}
              />
            </div>
            <div>
              <label className="block text-xs text-slate-500 mb-1">Action</label>
              <input
                className="bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm w-40"
                placeholder="Filter by action..."
                value={filters.action}
                onChange={(e) => setFilters((f) => ({ ...f, action: e.target.value }))}
              />
            </div>
            <Button
              size="sm"
              variant="ghost"
              onClick={() => setFilters({ startDate: '', endDate: '', user: '', action: '' })}
            >
              Clear
            </Button>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardContent className="p-0">
          <div className="overflow-x-auto max-h-[600px] overflow-y-auto">
            <table className="w-full text-sm">
              <thead className="sticky top-0 bg-slate-900 z-10">
                <tr className="text-left text-slate-400 text-xs uppercase border-b border-slate-800">
                  <th className="px-4 py-3 w-32">Timestamp</th>
                  <th className="px-4 py-3 w-24">User</th>
                  <th className="px-4 py-3 w-24">Account</th>
                  <th className="px-4 py-3 text-right w-24">Old Value</th>
                  <th className="px-4 py-3 text-right w-24">New Value</th>
                  <th className="px-4 py-3">Reason</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800">
                {filtered.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="text-center py-8 text-slate-500">
                      No entries match filters.
                    </td>
                  </tr>
                ) : (
                  filtered.slice(0, 500).map((e, i) => (
                    <tr key={e.id || i} className="hover:bg-slate-900/50">
                      <td
                        className="px-4 py-2 text-xs text-slate-400 whitespace-nowrap"
                        title={e.timestamp}
                      >
                        {formatRelativeTime(e.timestamp)}
                      </td>
                      <td className="px-4 py-2 text-xs text-slate-300">{e.userName}</td>
                      <td className="px-4 py-2 font-mono text-xs text-slate-400">
                        {e.accountName || e.accountId}
                      </td>
                      <td className="px-4 py-2 text-right tabular-nums text-slate-400">
                        {e.oldValue !== undefined
                          ? new Intl.NumberFormat('en-US', { minimumFractionDigits: 0 }).format(
                              e.oldValue
                            )
                          : '-'}
                      </td>
                      <td
                        className="px-4 py-2 text-right tabular-nums font-medium"
                        style={{
                          color: (e.newValue || 0) >= (e.oldValue || 0) ? '#4ade80' : '#f87171',
                        }}
                      >
                        {e.newValue !== undefined
                          ? new Intl.NumberFormat('en-US', { minimumFractionDigits: 0 }).format(
                              e.newValue
                            )
                          : '-'}
                      </td>
                      <td className="px-4 py-2 text-xs text-slate-500">{e.reason || '-'}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
          {entries.length > 500 && (
            <div className="p-3 text-center text-xs text-slate-500 border-t border-slate-800">
              Showing 500 of {entries.length} entries. Export for full dataset.
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Card, CardContent } from '@/components/ui/Card';
import { Mail, ArrowLeft, CheckCircle, AlertCircle, Lock, Clock } from 'lucide-react';

export default function ForgotPasswordPage() {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [sent, setSent] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [attempts, setAttempts] = useState(0);
  const [cooldown, setCooldown] = useState(0);

  useEffect(() => {
    document.title = 'FinPlan Pro - Reset Password';
  }, []);

  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    }
  }, [cooldown]);

  const validateEmail = (email: string): boolean => {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email);
  };

  const handleReset = async () => {
    setError('');

    if (!email) {
      setError('Please enter your email address.');
      return;
    }

    if (!validateEmail(email)) {
      setError('Please enter a valid email address.');
      return;
    }

    if (attempts >= 3) {
      setCooldown(60);
      setAttempts(0);
      return;
    }

    setLoading(true);
    setAttempts(attempts + 1);

    await new Promise((resolve) => setTimeout(resolve, 1500));

    setLoading(false);
    setSent(true);
  };

  const handleResend = () => {
    setSent(false);
    setEmail('');
  };

  if (sent) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-950 p-4">
        <Card className="w-full max-w-sm">
          <CardContent className="p-6 space-y-6">
            <div className="text-center">
              <div className="w-16 h-16 rounded-full bg-green-900/30 flex items-center justify-center mx-auto mb-4">
                <CheckCircle className="h-8 w-8 text-green-400" />
              </div>
              <h1 className="text-xl font-bold mb-2">Check Your Email</h1>
              <p className="text-sm text-slate-400 mb-4">
                We&apos;ve sent a password reset link to:
              </p>
              <div className="p-3 bg-slate-800 rounded-lg">
                <div className="flex items-center gap-2 justify-center">
