﻿import { useLocation } from 'react-router-dom';
import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useBudgetStore } from '@/store/budgetStore';
import { useGLStore } from '@/store/glStore';
import { ProgressStepper } from '@/components/ui/ProgressStepper';
import { Input } from '@/components/ui/Input';
import { Select } from '@/components/ui/Select';
import { Button } from '@/components/ui/Button';
import { Card, CardContent } from '@/components/ui/Card';
import { Alert } from '@/components/ui/Alert';
import { ArrowLeft, ArrowRight, Check, DollarSign } from 'lucide-react';

export default function BudgetCreatePage() {
  const [helpOpen, setHelpOpen] = useState(false);

  useEffect(() => {
    document.title = 'FinPlan Pro — Budget Create';
  }, []);

  const navigate = useNavigate();
  const { createBudget, budgets } = useBudgetStore();
  const { accounts } = useGLStore();
  const [step, setStep] = useState(0);
  const [form, setForm] = useState({
    name: '',
    fiscalYear: new Date().getFullYear(),
    baseCurrency: 'USD',
    description: '',
  });
  const [selectedAccountIds, setSelectedAccountIds] = useState<string[]>([]);
  const [amounts, setAmounts] = useState<Record<string, number>>({});
  const [formErrors, setFormErrors] = useState<Record<string, string>>({});

  const totalAmount = useMemo(() => {
    let total = 0;
    for (const key of Object.keys(amounts)) {
      total += amounts[key] || 0;
    }
    return total;
  }, [amounts]);

  const accountOptions = useMemo(
    () => [...accounts.map((a) => ({ value: a.id, label: a.code + ' — ' + a.name }))],
    [accounts]
  );

  const steps = useMemo(
    () => [
      {
        label: 'Details',
        status: (step > 0 ? 'done' : step === 0 ? 'current' : 'pending') as const,
        description: 'Budget info',
      },
      {
        label: 'Accounts',
        status: (step > 1 ? 'done' : step === 1 ? 'current' : 'pending') as const,
        description: 'Select accounts',
      },
      {
        label: 'Amounts',
        status: (step > 2 ? 'done' : step === 2 ? 'current' : 'pending') as const,
        description: 'Set amounts',
      },
      {
        label: 'Review',
        status: (step > 3 ? 'done' : step === 3 ? 'current' : 'pending') as const,
        description: 'Confirm & create',
      },
    ],
    [step]
  );

  const validateStep = (s: number): boolean => {
    const errors: Record<string, string> = {};
    if (s === 0) {
      if (!form.name || form.name.length < 2) errors.name = 'Name must be at least 2 characters';
    }
    if (s === 1) {
      if (selectedAccountIds.length === 0) errors.accounts = 'Select at least one account';
    }
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleNext = () => {
    if (validateStep(step)) setStep((s) => s + 1);
  };

  const handleCreate = (status: 'Draft' | 'InReview') => {
    if (totalAmount === 0 && !window.confirm('Total amount is $0. Create budget anyway?')) return;
    const budgetId = createBudget({
      name: form.name,
      fiscalYear: form.fiscalYear,
      baseCurrency: form.baseCurrency,
      description: form.description,
      selectedAccounts: selectedAccountIds.map((id) => ({
        accountId: id,
        months: Array.from({ length: 12 }, (_, m) => amounts[id + '-' + m] ?? 0),
      })),
      departments: [],
      entities: ['default'],
      status,
    });
    navigate('/budgets/' + budgetId);
  };

  if (accounts.length === 0) {
    return (
      <div className="p-12 text-center max-w-md mx-auto">
        <h2 className="text-xl font-semibold mb-2">No Accounts Defined</h2>
        <p className="text-slate-400 mb-6">
          Create your Chart of Accounts first before creating budgets.
        </p>
        <Button onClick={() => navigate('/data/chart-of-accounts')}>Set Up Accounts</Button>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <div className="flex items-center justify-between mb-6">
            <h1 className="text-2xl font-bold">Create Budget</h1>
            <button
              onClick={() => setHelpOpen(true)}
              className="p-2 hover:bg-slate-800 rounded-full text-slate-500 hover:text-white transition-colors"
              aria-label="Help"
            ></button>
          </div>
          <p className="text-sm text-slate-400 mt-1">
            Set up a new budget for planning and tracking
          </p>
        </div>
        <Button variant="ghost" onClick={() => navigate('/budgets')}>
          Cancel
        </Button>
      </div>

      <ProgressStepper steps={steps} currentStep={step} />

      {step === 0 && (
        <Card>
          <CardContent className="p-6 space-y-4">
            <h3 className="font-semibold">Budget Details</h3>
            <div>
              <label className="block text-xs font-medium text-slate-400 mb-1">Budget Name</label>
              <Input
                value={form.name}
                onChange={(e) => setForm({ ...form, name: e.target.value })}
                placeholder="e.g. FY2025 Annual Operating Budget"
                className={formErrors.name ? 'border-red-500' : ''}
              />
              {formErrors.name && <p className="text-xs text-red-400 mt-1">{formErrors.name}</p>}
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-400 mb-1">Fiscal Year</label>
              <Input
                type="number"
                value={form.fiscalYear}
                onChange={(e) =>
                  setForm({
                    ...form,
                    fiscalYear: parseInt(e.target.value) || new Date().getFullYear(),
                  })
                }
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-400 mb-1">Base Currency</label>
              <Select
                options={[{ value: 'USD', label: 'USD — US Dollar' }]}
                value={form.baseCurrency}
                onChange={(v) => setForm({ ...form, baseCurrency: v })}
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-400 mb-1">
                Description (optional)
              </label>
              <textarea
                className="w-full bg-slate-800 border border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-200 min-h-[80px] focus:outline-none focus:ring-2 focus:ring-blue-500"
                value={form.description}
                onChange={(e) => setForm({ ...form, description: e.target.value })}
                placeholder="Brief description of this budget..."
              />
            </div>
            <div className="flex justify-end">
              <Button onClick={handleNext}>
                Next
                <ArrowRight className="h-4 w-4 ml-2" />
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {step === 1 && (
        <Card>
          <CardContent className="p-6 space-y-4">
            <h3 className="font-semibold">Select Accounts</h3>
            <p className="text-sm text-slate-400">Choose the accounts to include in this budget.</p>
            {formErrors.accounts && (
              <Alert type="error" title="Validation Error" message={formErrors.accounts} />
            )}
            <div className="max-h-64 overflow-y-auto space-y-1">
              {accounts.map((a) => {
                const selected = selectedAccountIds.includes(a.id);
                return (
                  <label
                    key={a.id}
                    className={
                      'flex items-center gap-3 p-2 rounded-lg cursor-pointer transition-colors ' +
                      (selected
                        ? 'bg-blue-900/30 border border-blue-800/50'
                        : 'hover:bg-slate-800/50 border border-transparent')
                    }
                  >
                    <input
                      type="checkbox"
                      checked={selected}
                      onChange={() =>
                        setSelectedAccountIds((prev) =>
                          prev.includes(a.id) ? prev.filter((id) => id !== a.id) : [...prev, a.id]
                        )
                      }
                      className="rounded"
                    />
                    <div>
                      <div className="text-sm font-medium">
                        {a.code} — {a.name}
                      </div>
                      <div className="text-xs text-slate-500">
                        {a.type} · {a.category}
                      </div>
                    </div>
                  </label>
                );
              })}
            </div>
            <div className="flex justify-between">
              <Button variant="ghost" onClick={() => setStep(0)}>
                <ArrowLeft className="h-4 w-4 mr-2" />
                Back
              </Button>
              <Button onClick={handleNext} disabled={selectedAccountIds.length === 0}>
                Next
                <ArrowRight className="h-4 w-4 ml-2" />
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {step === 2 && (
        <Card>
          <CardContent className="p-6 space-y-4">
            <h3 className="font-semibold">Set Amounts</h3>
            <p className="text-sm text-slate-400">
              Enter monthly amounts for each selected account.
            </p>
            <div className="space-y-4 max-h-96 overflow-y-auto">
              {selectedAccountIds.map((id) => {
                const account = accounts.find((a) => a.id === id);
                return (
                  <div key={id} className="p-3 bg-slate-900 rounded-lg border border-slate-800">
                    <div className="text-sm font-medium mb-2">
                      {account?.code} — {account?.name}
                    </div>
                    <div className="grid grid-cols-4 gap-2">
                      {Array.from({ length: 12 }, (_, m) => {
                        const key = id + '-' + m;
                        return (
                          <div key={m}>
                            <label className="text-[10px] text-slate-500 block mb-0.5">
                              {new Date(form.fiscalYear, m).toLocaleString('default', {
                                month: 'short',
                              })}
                            </label>
                            <input
                              type="number"
                              className="w-full bg-slate-800 border border-slate-700 rounded px-2 py-1 text-xs text-right tabular-nums focus:outline-none focus:ring-1 focus:ring-blue-500"
                              value={amounts[key] ?? ''}
                              onChange={(e) =>
                                setAmounts((prev) => ({
                                  ...prev,
                                  [key]: parseFloat(e.target.value) || 0,
                                }))
                              }
                            />
                          </div>
                        );
                      })}
                    </div>
                    <div className="text-right text-xs text-slate-400 mt-1">
                      Total:{' '}
                      {new Intl.NumberFormat('en-US', {
                        style: 'currency',
                        currency: 'USD',
                        minimumFractionDigits: 0,
                      }).format(
                        Array.from({ length: 12 }, (_, m) => amounts[id + '-' + m] || 0).reduce(
                          (s, v) => s + v,
                          0
                        )
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
            <div className="text-sm text-slate-400">
              Total Budget:{' '}
              <span className="font-bold text-white">
                {new Intl.NumberFormat('en-US', {
                  style: 'currency',
                  currency: 'USD',
                  minimumFractionDigits: 0,
                }).format(totalAmount)}
              </span>
            </div>
            <div className="flex justify-between">
              <Button variant="ghost" onClick={() => setStep(1)}>
                <ArrowLeft className="h-4 w-4 mr-2" />
                Back
              </Button>
              <Button onClick={() => setStep(3)}>
                Next
                <ArrowRight className="h-4 w-4 ml-2" />
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {step === 3 && (
        <Card>
          <CardContent className="p-6 space-y-4">
            <h3 className="font-semibold">Review & Create</h3>
            <div className="space-y-2 text-sm">
              <div className="flex justify-between">
                <span className="text-slate-400">Name</span>
                <span className="font-medium">{form.name}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-400">Fiscal Year</span>
                <span>{form.fiscalYear}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-400">Currency</span>
                <span>{form.baseCurrency}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-400">Accounts</span>
                <span>{selectedAccountIds.length} selected</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-400">Total Amount</span>
                <span className="font-bold text-lg">
                  {new Intl.NumberFormat('en-US', {
                    style: 'currency',
                    currency: 'USD',
                    minimumFractionDigits: 0,
                  }).format(totalAmount)}
                </span>
              </div>
            </div>
            {form.description && (
              <div className="text-sm text-slate-400 p-3 bg-slate-900 rounded">
                {form.description}
              </div>
            )}
            <div className="flex gap-3 pt-4">
              <Button variant="ghost" onClick={() => setStep(2)}>
                <ArrowLeft className="h-4 w-4 mr-2" />
                Back
              </Button>
              <Button variant="secondary" onClick={() => handleCreate('Draft')}>
                <Check className="h-4 w-4 mr-2" />
                Save as Draft
              </Button>
              <Button onClick={() => handleCreate('InReview')}>
                <DollarSign className="h-4 w-4 mr-2" />
                Submit for Review
              </Button>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

﻿import { useLocation, useParams, useNavigate, Link } from 'react-router-dom';
import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useBudgetStore } from '@/store/budgetStore';
import { useGLStore } from '@/store/glStore';
import { useAuthStore } from '@/store/authStore';
import { Button } from '@/components/ui/Button';
import { Badge } from '@/components/ui/Badge';
import { Card, CardContent } from '@/components/ui/Card';
import { Skeleton } from '@/components/ui/Skeleton';
import {
  ArrowLeft,
  Undo2,
  Redo2,
  Lock,
  Unlock,
  Save,
  Send,
  CheckCircle,
  XCircle,
  History,
} from 'lucide-react';

function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(n);
}

export default function BudgetDetailPage() {
  const [helpOpen, setHelpOpen] = useState(false);
  const { user } = useAuthStore();

  useEffect(() => {
    document.title = 'FinPlan Pro — Budget Detail';
  }, []);

  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();

  const {
    budgets,
    lineItems,
    activeBudgetId,
    setActiveBudget,
    updateCell,
    undo,
    redo,
    historyIndex,
    history,
    submitBudget,
    approveBudget,
    rejectBudget,
    updateBudget,
  } = useBudgetStore();
  const { accounts } = useGLStore();

  const budget = budgets.find((b) => b.id === id);

  useEffect(() => {
    if (id && id !== activeBudgetId) {
      setActiveBudget(id);
    }
  }, [id, activeBudgetId, setActiveBudget]);

  const [editCell, setEditCell] = useState<{ lineItemId: string; month: number } | null>(null);
  const [editValue, setEditValue] = useState('');

  const budgetLineItems = useMemo(() => {
    return lineItems.filter((li) => li.budgetId === id);
  }, [lineItems, id]);

  const groupedByAccount = useMemo(() => {
    const map = new Map<string, typeof lineItems>();
    for (const li of budgetLineItems) {
      const existing = map.get(li.accountId) || [];
      existing.push(li);
      map.set(li.accountId, existing);
    }
    return Array.from(map.entries()).map(([accountId, items]) => ({
      accountId,
      accountName:
        items[0]?.accountName || accounts.find((a) => a.id === accountId)?.name || accountId,
      accountCode: items[0]?.accountCode || accounts.find((a) => a.id === accountId)?.code || '',
      items: items.sort((a, b) => a.month - b.month),
      total: items.reduce((s, li) => s + li.amount, 0),
    }));
  }, [budgetLineItems, accounts]);

  const grandTotal = useMemo(
    () => groupedByAccount.reduce((s, g) => s + g.total, 0),
    [groupedByAccount]
  );

  const canUndo = historyIndex > 0;
  const canRedo = historyIndex < history.length - 1;

  const handleCellClick = useCallback((lineItemId: string, month: number, currentValue: number) => {
    setEditCell({ lineItemId, month });
    setEditValue(String(currentValue));
  }, []);

  const handleCellSave = useCallback(() => {
    if (editCell) {
      const val = parseFloat(editValue) || 0;
      updateCell(editCell.lineItemId, val);
      setEditCell(null);
    }
  }, [editCell, editValue, updateCell]);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') handleCellSave();
      if (e.key === 'Escape') setEditCell(null);
    },
    [handleCellSave]
  );

  if (user?.role === 'Viewer') {
    return (
      <div className="p-12 text-center">
        <h2 className="text-xl font-bold text-white mb-2">Access Restricted</h2>
        <p className="text-slate-400 mb-6">Viewers cannot access the budget editor.</p>
        <Link to="/dashboard" className="text-blue-400 hover:underline font-medium">
          Back to Dashboard
        </Link>
      </div>
    );
  }

  const months = [
    'Jan',
    'Feb',
    'Mar',
    'Apr',
    'May',
    'Jun',
    'Jul',
    'Aug',
    'Sep',
    'Oct',
    'Nov',
    'Dec',
  ];

  if (!budget) {
    return (
      <div className="p-12 text-center">
        <h2 className="text-xl font-semibold mb-2">Budget Not Found</h2>
        <p className="text-slate-400 mb-4">
          The budget you&apos;re looking for doesn&apos;t exist.
        </p>
        <Button onClick={() => navigate('/budgets')}>Back to Budgets</Button>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button
            onClick={() => navigate('/budgets')}
            className="p-2 rounded-lg hover:bg-slate-800 text-slate-400 transition-colors"
          >
            <ArrowLeft className="h-5 w-5" />
          </button>
          <div>
            <div className="flex items-center justify-between mb-6">
              <h1 className="text-2xl font-bold">{budget.name}</h1>
              <button
                onClick={() => setHelpOpen(true)}
                className="p-2 hover:bg-slate-800 rounded-full text-slate-500 hover:text-white transition-colors"
                aria-label="Help"
              ></button>
            </div>
            <p className="text-sm text-slate-400 mt-0.5">
              FY{budget.fiscalYear} · {budgetLineItems.length} line items ·{' '}
              {formatCurrency(grandTotal)}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Badge
            variant={
              budget.status === 'Approved'
                ? 'default'
                : budget.status === 'InReview'
                  ? 'secondary'
                  : budget.status === 'Rejected'
                    ? 'destructive'
                    : 'outline'
            }
          >
            {budget.status}
          </Badge>
          <button
            onClick={undo}
            disabled={!canUndo}
            className={
              'p-2 rounded-lg transition-colors ' +
              (canUndo ? 'hover:bg-slate-800 text-slate-400' : 'text-slate-700 cursor-not-allowed')
            }
            title="Undo"
          >
            <Undo2 className="h-4 w-4" />
          </button>
          <button
            onClick={redo}
            disabled={!canRedo}
            className={
              'p-2 rounded-lg transition-colors ' +
              (canRedo ? 'hover:bg-slate-800 text-slate-400' : 'text-slate-700 cursor-not-allowed')
            }
            title="Redo"
          >
            <Redo2 className="h-4 w-4" />
          </button>
          {budget.status === 'Draft' && (
            <>
              <Button
                size="sm"
                variant="ghost"
                onClick={() => {
                  if (window.confirm('Submit this budget for approval?')) submitBudget(budget.id);
                }}
                title="Submit for approval"
              >
                <Send className="h-3.5 w-3.5 mr-1.5" />
                Submit
              </Button>
              <Button
                size="sm"
                variant="ghost"
                onClick={() => {
                  if (window.confirm('Lock this budget? This prevents further edits.'))
                    updateBudget(budget.id, { status: 'Locked' });
                }}
                title="Lock budget"
              >
                <Lock className="h-3.5 w-3.5 mr-1.5" />
                Lock
              </Button>
            </>
          )}
          {budget.status === 'InReview' && (
            <>
              <Button
                size="sm"
                variant="ghost"
                onClick={() => {
                  if (window.confirm('Approve this budget?')) approveBudget(budget.id);
                }}
                className="text-green-400"
              >
                <CheckCircle className="h-3.5 w-3.5 mr-1.5" />
                Approve
              </Button>
              <Button
                size="sm"
                variant="ghost"
                onClick={() => {
                  if (window.confirm('Reject this budget?')) rejectBudget(budget.id);
                }}
                className="text-red-400"
              >
                <XCircle className="h-3.5 w-3.5 mr-1.5" />
                Reject
              </Button>
            </>
          )}
        </div>
      </div>

      <Card>
        <CardContent className="p-0 overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-slate-400 text-xs uppercase border-b border-slate-800">
                <th className="px-4 py-3 w-24 sticky left-0 bg-slate-900 z-10">Account</th>
                {months.map((m) => (
                  <th key={m} className="px-2 py-3 text-right w-24">
                    {m}
                  </th>
                ))}
                <th className="px-4 py-3 text-right w-28">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800">
              {groupedByAccount.length === 0 ? (
                <tr>
                  <td colSpan={14} className="text-center py-8 text-slate-500">
                    No line items in this budget yet.
                  </td>
                </tr>
              ) : (
                groupedByAccount.map((group) => (
