import React, { useState, useMemo } from 'react';
import { Button } from '@/components/ui/Button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import { Input } from '@/components/ui/Input';
import { Select } from '@/components/ui/Select';
import { FinancialTable } from '@/components/ui/FinancialTable';
import { Skeleton } from '@/components/ui/Skeleton';
import { ConsolidationEngine, EntityData, OwnershipStructure } from '@/engines/ConsolidationEngine';
import { Plus, Trash2, Edit2, LayoutGrid, List } from 'lucide-react';

interface Entity {
  id: string;
  name: string;
  code: string;
  currency: string;
  country: string;
  parentId: string | null;
  ownershipPct: number;
}

const currencies = ['USD', 'EUR', 'GBP', 'JPY', 'CAD', 'AUD'];

export default function ConsolidationDashboard() {
  const [entities, setEntities] = useState<Entity[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEntity, setEditingEntity] = useState<Entity | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    code: '',
    currency: 'USD',
    country: '',
    parentId: '',
    ownershipPct: 100,
  });

  const handleAdd = () => {
    setEditingEntity(null);
    setFormData({
      name: '',
      code: '',
      currency: 'USD',
      country: '',
      parentId: '',
      ownershipPct: 100,
    });
    setIsModalOpen(true);
  };

  const handleEdit = (entity: Entity) => {
    setEditingEntity(entity);
    setFormData({
      name: entity.name,
      code: entity.code,
      currency: entity.currency,
      country: entity.country,
      parentId: entity.parentId || '',
      ownershipPct: entity.ownershipPct,
    });
    setIsModalOpen(true);
  };

  const handleDelete = (entity: Entity) => {
    const hasChildren = entities.some((e) => e.parentId === entity.id);
    if (hasChildren) {
      alert(`Cannot delete ${entity.name} because it has child entities.`);
      return;
    }
    if (window.confirm(`Delete ${entity.name}?`)) {
      setEntities(entities.filter((e) => e.id !== entity.id));
    }
  };

  const validate = () => {
    if (formData.name.length < 2) return 'Name must be at least 2 characters';
    if (formData.code.length < 3 || formData.code.length > 8) return 'Code must be 3-8 characters';
    if (
      entities.some(
        (e) => e.code === formData.code && (!editingEntity || e.id !== editingEntity.id)
      )
    ) {
      return 'Code must be unique';
    }
    if (formData.parentId) {
      if (editingEntity && formData.parentId === editingEntity.id)
        return 'Entity cannot be its own parent';

      // Circular check
      let curr = formData.parentId;
      while (curr) {
        const parent = entities.find((e) => e.id === curr);
        if (parent && editingEntity && parent.id === editingEntity.id)
          return 'Circular reference detected';
        curr = parent?.parentId || '';
      }
    }
    return null;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const err = validate();
    if (err) {
      alert(err);
      return;
    }

    const newEntity: Entity = {
      id: editingEntity?.id || `ent-${Date.now()}`,
      name: formData.name,
      code: formData.code,
      currency: formData.currency,
      country: formData.country,
      parentId: formData.parentId || null,
      ownershipPct: formData.ownershipPct,
    };

    if (editingEntity) {
      setEntities(entities.map((e) => (e.id === editingEntity.id ? newEntity : e)));
    } else {
      setEntities([...entities, newEntity]);
    }
    setIsModalOpen(false);
  };

  const consolidatedData = useMemo(() => {
    if (entities.length === 0) return null;

    // Mock data for consolidation logic verification
    const entityData: EntityData[] = entities.map((e) => ({
      entityId: e.id,
      entityName: e.name,
      currency: e.currency,
      entries: [
        {
          id: `re-${e.id}`,
          entityId: e.id,
          accountCode: '4000',
          accountName: 'Revenue',
          amount: 100000,
          date: '2024-01-01',
          period: '2024-01',
        },
        {
          id: `ex-${e.id}`,
          entityId: e.id,
          accountCode: '5000',
          accountName: 'Operating Expenses',
          amount: -60000,
          date: '2024-01-01',
          period: '2024-01',
        },
      ],
    }));

    const ownerships: OwnershipStructure[] = entities
      .filter((e) => e.parentId)
      .map((e) => ({
        parentId: e.parentId!,
        childId: e.id,
        ownershipPct: e.ownershipPct,
      }));

    return ConsolidationEngine.consolidate(entityData, ownerships);
  }, [entities]);

  if (isLoading)
    return (
      <div className="p-6 space-y-4">
        <Skeleton className="h-10 w-48" />
        <Skeleton className="h-64 w-full" />
      </div>
    );
  if (error)
    return (
      <div className="p-12 text-center text-red-500">
        {error}{' '}
        <Button onClick={() => setError(null)} className="ml-4">
          Retry
        </Button>
      </div>
    );

  return (
    <div className="p-6 space-y-8">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold text-[var(--text-primary)]">
            Legal Entity Consolidation
          </h1>
          <p className="text-[var(--text-secondary)] mt-1">
            Manage entity structure and view consolidated financial results.
          </p>
        </div>
        <Button onClick={handleAdd}>
          <Plus className="h-4 w-4 mr-2" /> Add Entity
        </Button>
      </div>

      <Card className="border-[var(--border-subtle)] bg-[var(--bg-surface)]">
        <CardHeader>
          <CardTitle>Entity Structure</CardTitle>
        </CardHeader>
        <CardContent>
          {entities.length === 0 ? (
            <div className="py-12 text-center text-[var(--text-secondary)]">
              No entities defined yet. Add your first entity to start consolidation.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm">
                <thead className="border-b border-[var(--border-subtle)] text-[var(--text-secondary)] font-medium">
                  <tr>
                    <th className="py-3 px-4">Name</th>
                    <th className="py-3 px-4">Code</th>
                    <th className="py-3 px-4">Currency</th>
                    <th className="py-3 px-4">Country</th>
                    <th className="py-3 px-4">Parent Entity</th>
                    <th className="py-3 px-4">Ownership %</th>
                    <th className="py-3 px-4 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[var(--border-subtle)] text-[var(--text-primary)]">
                  {entities.map((entity) => (
                    <tr key={entity.id} className="hover:bg-[var(--bg-muted)] transition-colors">
                      <td className="py-3 px-4 font-medium">{entity.name}</td>
                      <td className="py-3 px-4 font-mono">{entity.code}</td>
                      <td className="py-3 px-4">{entity.currency}</td>
                      <td className="py-3 px-4">{entity.country}</td>
                      <td className="py-3 px-4">
                        {entities.find((e) => e.id === entity.parentId)?.name || '-'}
                      </td>
                      <td className="py-3 px-4">{entity.ownershipPct}%</td>
                      <td className="py-3 px-4 text-right space-x-2">
                        <Button variant="outline" size="sm" onClick={() => handleEdit(entity)}>
                          <Edit2 className="h-3 w-3" />
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          className="text-red-500 border-red-500/20 hover:bg-red-500/10"
                          onClick={() => handleDelete(entity)}
                        >
                          <Trash2 className="h-3 w-3" />
                        </Button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>

      {entities.length > 0 && (
        <Card className="border-[var(--border-subtle)] bg-[var(--bg-surface)]">
          <CardHeader>
            <CardTitle>Consolidated Profit & Loss (Draft)</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-6">
              <div className="flex gap-4 items-center">
                <div className="text-sm text-[var(--text-secondary)]">Period:</div>
                <Select
                  options={Array.from({ length: 12 }, (_, i) => ({
                    value: `2024-${String(i + 1).padStart(2, '0')}`,
                    label: new Date(2024, i).toLocaleString('default', {
                      month: 'long',
                      year: 'numeric',
                    }),
                  }))}
                  value="2024-01"
                  onChange={() => {}}
                />
              </div>

              <div className="overflow-x-auto">
                <table className="w-full text-left text-sm tabular-nums">
                  <thead className="border-b border-[var(--border-subtle)] text-[var(--text-secondary)]">
                    <tr>
                      <th className="py-3 px-4">Account</th>
                      {entities.map((e) => (
                        <th key={e.id} className="py-3 px-4 text-right">
                          {e.name}
                        </th>
                      ))}
                      <th className="py-3 px-4 text-right">Eliminations</th>
                      <th className="py-3 px-4 text-right font-bold text-blue-400">Consolidated</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[var(--border-subtle)] text-[var(--text-primary)]">
                    <tr className="hover:bg-[var(--bg-muted)]">
                      <td className="py-3 px-4">Revenue</td>
                      {entities.map((e) => (
                        <td key={e.id} className="py-3 px-4 text-right">
                          $100,000
                        </td>
                      ))}
                      <td className="py-3 px-4 text-right text-red-400">-$0</td>
                      <td className="py-3 px-4 text-right font-bold">
                        ${(entities.length * 100000).toLocaleString()}
                      </td>
                    </tr>
                    <tr className="hover:bg-[var(--bg-muted)]">
                      <td className="py-3 px-4">Operating Expenses</td>
                      {entities.map((e) => (
                        <td key={e.id} className="py-3 px-4 text-right">
                          ($60,000)
                        </td>
                      ))}
                      <td className="py-3 px-4 text-right">$0</td>
                      <td className="py-3 px-4 text-right font-bold">
                        (${(entities.length * 60000).toLocaleString()})
                      </td>
                    </tr>
                    <tr className="bg-[var(--bg-muted)] font-bold">
                      <td className="py-3 px-4">Net Income</td>
                      {entities.map((e) => (
                        <td key={e.id} className="py-3 px-4 text-right text-green-400">
                          $40,000
                        </td>
                      ))}
                      <td className="py-3 px-4 text-right">$0</td>
                      <td className="py-3 px-4 text-right text-blue-400">
                        ${(entities.length * 40000).toLocaleString()}
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
          <Card className="w-full max-w-lg mx-4">
            <CardHeader>
              <CardTitle>{editingEntity ? 'Edit Entity' : 'Add New Entity'}</CardTitle>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">Name</label>
                    <Input
                      required
                      placeholder="e.g. US Parent"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">Code</label>
                    <Input
                      required
                      maxLength={8}
                      placeholder="e.g. US001"
                      value={formData.code}
                      onChange={(e) => setFormData({ ...formData, code: e.target.value })}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">
                      Currency
                    </label>
                    <Select
                      options={currencies.map((c) => ({ value: c, label: c }))}
                      value={formData.currency}
                      onChange={(val) => setFormData({ ...formData, currency: val })}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">
                      Country
                    </label>
                    <Input
                      placeholder="e.g. United States"
                      value={formData.country}
                      onChange={(e) => setFormData({ ...formData, country: e.target.value })}
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">
                      Parent Entity
                    </label>
                    <Select
                      options={[
                        { value: '', label: 'No Parent' },
                        ...entities
                          .filter((e) => !editingEntity || e.id !== editingEntity.id)
                          .map((e) => ({ value: e.id, label: e.name })),
                      ]}
                      value={formData.parentId}
                      onChange={(val) => setFormData({ ...formData, parentId: val })}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-xs font-medium text-[var(--text-secondary)]">
                      Ownership %
                    </label>
                    <Input
                      type="number"
                      min={0}
                      max={100}
                      value={formData.ownershipPct}
                      onChange={(e) =>
                        setFormData({ ...formData, ownershipPct: Number(e.target.value) })
                      }
                    />
                  </div>
                </div>

                <div className="flex justify-end gap-3 pt-4">
                  <Button variant="outline" type="button" onClick={() => setIsModalOpen(false)}>
                    Cancel
                  </Button>
                  <Button type="submit">{editingEntity ? 'Update Entity' : 'Create Entity'}</Button>
                </div>
              </form>
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

import { useState, useCallback, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useGLStore } from '@/store/glStore';
import { Button } from '@/components/ui/Button';
import { Card, CardContent } from '@/components/ui/Card';
import { Modal } from '@/components/ui/Modal';
import { Plus, Trash2, RefreshCw, AlertCircle } from 'lucide-react';
import type { ExchangeRate } from '@/types';

const INITIAL_RATES: ExchangeRate[] = [
  { id: '1', fromCurrency: 'USD', toCurrency: 'EUR', rate: 0.92, effectiveDate: '2026-01-01' },
  { id: '2', fromCurrency: 'USD', toCurrency: 'GBP', rate: 0.79, effectiveDate: '2026-01-01' },
  { id: '3', fromCurrency: 'USD', toCurrency: 'JPY', rate: 149.5, effectiveDate: '2026-01-01' },
];

const CURRENCIES = ['USD', 'EUR', 'GBP', 'JPY', 'CHF', 'CAD', 'AUD', 'CNY', 'INR', 'BRL'];

interface RateForm {
  fromCurrency: string;
  toCurrency: string;
  rate: string;
  effectiveDate: string;
}

const EMPTY_FORM: RateForm = {
  fromCurrency: 'USD',
  toCurrency: 'EUR',
  rate: '',
  effectiveDate: '',
};

export default function FXRatesPage() {
  const { entries } = useGLStore();
  const navigate = useNavigate();
  const [rates, setRates] = useState<ExchangeRate[]>(INITIAL_RATES);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState<RateForm>(EMPTY_FORM);
  const [errors, setErrors] = useState<Partial<Record<keyof RateForm, string>>>({});
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const validate = useCallback(
    (f: RateForm): Partial<Record<keyof RateForm, string>> => {
      const e: Partial<Record<keyof RateForm, string>> = {};
      if (!f.rate || isNaN(Number(f.rate)) || Number(f.rate) <= 0)
        e.rate = 'Rate must be a positive number';
      if (f.fromCurrency === f.toCurrency) e.toCurrency = 'Currencies must differ';
      if (rates.some((r) => r.fromCurrency === f.fromCurrency && r.toCurrency === f.toCurrency))
        e.toCurrency = 'This currency pair already exists';
      if (!f.effectiveDate) e.effectiveDate = 'Date is required';
      return e;
    },
    [rates]
  );

  const handleAdd = useCallback(() => {
    const errs = validate(form);
    setErrors(errs);
    if (Object.keys(errs).length > 0) return;
    const newRate: ExchangeRate = {
      id: Date.now().toString(),
      fromCurrency: form.fromCurrency,
      toCurrency: form.toCurrency,
      rate: Number(form.rate),
      effectiveDate: form.effectiveDate,
    };
    setRates((prev) => [...prev, newRate]);
    setForm(EMPTY_FORM);
    setShowForm(false);
  }, [form, validate]);

  const handleDelete = useCallback((id: string) => {
    setRates((prev) => prev.filter((r) => r.id !== id));
    setDeleteId(null);
  }, []);

  if (entries.length === 0)
    return (
      <div className="p-12 text-center">
        <h2 className="text-xl font-semibold mb-2">No Data</h2>
        <p className="text-slate-400 mb-4">Import data to enable FX translation.</p>
        <Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>
      </div>
    );

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">FX Rates</h1>
          <p className="text-sm text-slate-400 mt-1">
            {rates.length} rate{rates.length !== 1 ? 's' : ''} configured
          </p>
        </div>
        <Button
          size="sm"
          onClick={() => {
            setForm(EMPTY_FORM);
            setErrors({});
            setShowForm(true);
          }}
        >
          <Plus className="h-3.5 w-3.5 mr-1.5" />
          Add Rate
        </Button>
      </div>

      <Card>
        <CardContent className="p-0">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-slate-400 text-xs uppercase border-b border-slate-800">
                <th className="px-4 py-3">From</th>
                <th className="px-4 py-3">To</th>
                <th className="px-4 py-3 text-right">Rate</th>
                <th className="px-4 py-3">Effective Date</th>
                <th className="px-4 py-3 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800">
              {rates.length === 0 ? (
                <tr>
                  <td colSpan={5} className="text-center py-12 text-slate-500">
                    <AlertCircle className="h-8 w-8 mx-auto mb-2 text-slate-600" />
                    No exchange rates configured. Add rates to enable multi-currency translation.
                  </td>
                </tr>
              ) : (
                rates.map((r) => (
                  <tr key={r.id} className="hover:bg-slate-900/50">
                    <td className="px-4 py-3 font-mono">{r.fromCurrency}</td>
                    <td className="px-4 py-3 font-mono">{r.toCurrency}</td>
                    <td className="px-4 py-3 text-right tabular-nums font-medium">
                      {r.rate.toFixed(4)}
                    </td>
                    <td className="px-4 py-3 text-slate-400">{r.effectiveDate}</td>
                    <td className="px-4 py-3 text-right">
                      <Button variant="ghost" size="xs" onClick={() => setDeleteId(r.id)}>
                        <Trash2 className="h-3.5 w-3.5 text-red-400" />
                      </Button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </CardContent>
      </Card>

      {/* Add Rate Modal */}
      <Modal isOpen={showForm} onClose={() => setShowForm(false)}>
        <div className="p-6 space-y-4">
          <h2 className="text-lg font-bold text-white">Add Exchange Rate</h2>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs text-slate-400 mb-1">From Currency</label>
              <select
                value={form.fromCurrency}
                onChange={(e) => setForm((f) => ({ ...f, fromCurrency: e.target.value }))}
                className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white"
              >
                {CURRENCIES.map((c) => (
                  <option key={c} value={c}>
                    {c}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">To Currency</label>
              <select
                value={form.toCurrency}
                onChange={(e) => setForm((f) => ({ ...f, toCurrency: e.target.value }))}
                className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white"
              >
                {CURRENCIES.map((c) => (
                  <option key={c} value={c}>
                    {c}
                  </option>
                ))}
              </select>
              {errors.toCurrency && (
                <p className="text-xs text-red-400 mt-1">{errors.toCurrency}</p>
              )}
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Rate</label>
              <input
                type="number"
                step="any"
                min="0"
                value={form.rate}
                onChange={(e) => setForm((f) => ({ ...f, rate: e.target.value }))}
                className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white"
                placeholder="0.0000"
              />
              {errors.rate && <p className="text-xs text-red-400 mt-1">{errors.rate}</p>}
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Effective Date</label>
              <input
                type="date"
                value={form.effectiveDate}
                onChange={(e) => setForm((f) => ({ ...f, effectiveDate: e.target.value }))}
                className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white"
              />
              {errors.effectiveDate && (
                <p className="text-xs text-red-400 mt-1">{errors.effectiveDate}</p>
              )}
            </div>
          </div>
          <div className="flex justify-end gap-2 pt-2">
            <Button variant="ghost" onClick={() => setShowForm(false)}>
              Cancel
            </Button>
            <Button onClick={handleAdd}>Add Rate</Button>
          </div>
        </div>
      </Modal>

      {/* Delete Confirmation Modal */}
      <Modal isOpen={deleteId !== null} onClose={() => setDeleteId(null)}>
        <div className="p-6 space-y-4">
          <h2 className="text-lg font-bold text-white">Delete Rate</h2>
          <p className="text-slate-400">
            Are you sure you want to delete this exchange rate? This action cannot be undone.
          </p>
          <div className="flex justify-end gap-2">
            <Button variant="ghost" onClick={() => setDeleteId(null)}>
              Cancel
            </Button>
            <Button
              className="bg-red-600 hover:bg-red-700"
              onClick={() => deleteId && handleDelete(deleteId)}
            >
              Delete
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
}

import { useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useGLStore } from '@/store/glStore';
import { Button } from '@/components/ui/Button';
import { Card, CardContent } from '@/components/ui/Card';
import { Badge } from '@/components/ui/Badge';
import { Modal } from '@/components/ui/Modal';
import { Shield, Plus, Pencil, Trash2, AlertCircle } from 'lucide-react';

type HedgeStatus = 'Active' | 'Expired' | 'Settled';

interface HedgePosition {
  id: string;
  instrument: string;
  notionalAmount: number;
  contractedRate: number;
  maturityDate: string;
  status: HedgeStatus;
  currency: string;
}

const INITIAL_HEDGES: HedgePosition[] = [];

const STATUS_VARIANT: Record<HedgeStatus, 'default' | 'secondary' | 'destructive' | 'outline'> = {
  Active: 'default',
  Expired: 'secondary',
  Settled: 'outline',
};

interface HedgeForm {
  instrument: string;
  notionalAmount: string;
  contractedRate: string;
  maturityDate: string;
  status: HedgeStatus;
  currency: string;
}

const EMPTY_FORM: HedgeForm = {
  instrument: '',
  notionalAmount: '',
  contractedRate: '',
  maturityDate: '',
  status: 'Active',
  currency: 'USD',
};

const CURRENCIES = ['USD', 'EUR', 'GBP', 'JPY', 'CHF', 'CAD', 'AUD'];
const INSTRUMENTS = [
  'Forward Contract',
  'Currency Option',
  'Cross-Currency Swap',
  'Non-Deliverable Forward',
];

function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
  }).format(n);
}

export default function HedgeManagementPage() {
  const { entries } = useGLStore();
  const navigate = useNavigate();
  const [hedges, setHedges] = useState<HedgePosition[]>(INITIAL_HEDGES);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<HedgeForm>(EMPTY_FORM);
  const [errors, setErrors] = useState<Partial<Record<keyof HedgeForm, string>>>({});
  const [deleteId, setDeleteId] = useState<string | null>(null);

  const validate = useCallback((f: HedgeForm): Partial<Record<keyof HedgeForm, string>> => {
    const e: Partial<Record<keyof HedgeForm, string>> = {};
    if (!f.instrument.trim()) e.instrument = 'Instrument is required';
    if (!f.notionalAmount || isNaN(Number(f.notionalAmount)) || Number(f.notionalAmount) <= 0)
      e.notionalAmount = 'Amount must be positive';
    if (!f.contractedRate || isNaN(Number(f.contractedRate)) || Number(f.contractedRate) <= 0)
      e.contractedRate = 'Rate must be positive';
    if (!f.maturityDate) e.maturityDate = 'Maturity date is required';
    return e;
  }, []);

  const openAdd = useCallback(() => {
    setForm(EMPTY_FORM);
    setErrors({});
    setEditingId(null);
    setShowForm(true);
  }, []);

  const openEdit = useCallback((h: HedgePosition) => {
    setForm({
      instrument: h.instrument,
      notionalAmount: h.notionalAmount.toString(),
      contractedRate: h.contractedRate.toString(),
      maturityDate: h.maturityDate,
      status: h.status,
      currency: h.currency,
    });
    setErrors({});
    setEditingId(h.id);
    setShowForm(true);
  }, []);

  const handleSave = useCallback(() => {
    const errs = validate(form);
    setErrors(errs);
    if (Object.keys(errs).length > 0) return;

    if (editingId) {
      setHedges((prev) =>
        prev.map((h) =>
          h.id === editingId
            ? {
                ...h,
                instrument: form.instrument,
                notionalAmount: Number(form.notionalAmount),
                contractedRate: Number(form.contractedRate),
                maturityDate: form.maturityDate,
                status: form.status,
                currency: form.currency,
              }
            : h
        )
      );
    } else {
      const newHedge: HedgePosition = {
        id: Date.now().toString(),
        instrument: form.instrument,
        notionalAmount: Number(form.notionalAmount),
        contractedRate: Number(form.contractedRate),
        maturityDate: form.maturityDate,
        status: form.status,
        currency: form.currency,
      };
      setHedges((prev) => [...prev, newHedge]);
    }
    setShowForm(false);
    setEditingId(null);
  }, [form, editingId, validate]);

  const handleDelete = useCallback((id: string) => {
    setHedges((prev) => prev.filter((h) => h.id !== id));
    setDeleteId(null);
  }, []);

  if (entries.length === 0)
    return (
      <div className="p-12 text-center">
        <Shield className="h-10 w-10 text-slate-400 mx-auto mb-4" />
        <h2 className="text-xl font-semibold mb-2">No Data</h2>
        <p className="text-slate-400 mb-4">Import data to manage FX hedges.</p>
        <Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>
      </div>
    );

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">Hedge Management</h1>
          <p className="text-sm text-slate-400 mt-1">
            {hedges.length} position{hedges.length !== 1 ? 's' : ''} tracked
          </p>
        </div>
        <Button size="sm" onClick={openAdd}>
          <Plus className="h-3.5 w-3.5 mr-1.5" />
          Add Position
        </Button>
      </div>

      <Card>
        <CardContent className="p-0">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-slate-400 text-xs uppercase border-b border-slate-800">
                <th className="px-4 py-3">Instrument</th>
                <th className="px-4 py-3">Currency</th>
                <th className="px-4 py-3 text-right">Notional</th>
                <th className="px-4 py-3 text-right">Rate</th>
                <th className="px-4 py-3">Maturity</th>
                <th className="px-4 py-3">Status</th>
                <th className="px-4 py-3 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800">
              {hedges.length === 0 ? (
                <tr>
                  <td colSpan={7} className="text-center py-12 text-slate-500">
                    <AlertCircle className="h-8 w-8 mx-auto mb-2 text-slate-600" />
                    No hedging positions. Add a position to track FX exposure.
                  </td>
                </tr>
              ) : (
                hedges.map((h) => (
                  <tr key={h.id} className="hover:bg-slate-900/50">
                    <td className="px-4 py-3">{h.instrument}</td>
                    <td className="px-4 py-3 font-mono">{h.currency}</td>
                    <td className="px-4 py-3 text-right tabular-nums">
                      {formatCurrency(h.notionalAmount)}
                    </td>
                    <td className="px-4 py-3 text-right tabular-nums">
                      {h.contractedRate.toFixed(4)}
                    </td>
                    <td className="px-4 py-3 text-slate-400">{h.maturityDate}</td>
                    <td className="px-4 py-3">
                      <Badge variant={STATUS_VARIANT[h.status]}>{h.status}</Badge>
                    </td>
                    <td className="px-4 py-3 text-right space-x-1">
                      <Button variant="ghost" size="xs" onClick={() => openEdit(h)}>
                        <Pencil className="h-3.5 w-3.5" />
                      </Button>
                      <Button variant="ghost" size="xs" onClick={() => setDeleteId(h.id)}>
                        <Trash2 className="h-3.5 w-3.5 text-red-400" />
                      </Button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </CardContent>
      </Card>

      {/* Add/Edit Modal */}
      <Modal isOpen={showForm} onClose={() => setShowForm(false)}>
        <div className="p-6 space-y-4">
          <h2 className="text-lg font-bold text-white">
            {editingId ? 'Edit Position' : 'Add Position'}
          </h2>
          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-2">
              <label className="block text-xs text-slate-400 mb-1">Instrument</label>
              <select
                value={form.instrument}
                onChange={(e) => setForm((f) => ({ ...f, instrument: e.target.value }))}
                className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white"
              >
                <option value="">Select instrument...</option>
                {INSTRUMENTS.map((i) => (
                  <option key={i} value={i}>
                    {i}
                  </option>
                ))}
              </select>
              {errors.instrument && (
                <p className="text-xs text-red-400 mt-1">{errors.instrument}</p>
              )}
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Currency</label>
              <select
                value={form.currency}
                onChange={(e) => setForm((f) => ({ ...f, currency: e.target.value }))}
                className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white"
              >
                {CURRENCIES.map((c) => (
                  <option key={c} value={c}>
                    {c}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Notional Amount</label>
              <input
                type="number"
                value={form.notionalAmount}
                onChange={(e) => setForm((f) => ({ ...f, notionalAmount: e.target.value }))}
                className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white"
                placeholder="0"
              />
              {errors.notionalAmount && (
                <p className="text-xs text-red-400 mt-1">{errors.notionalAmount}</p>
              )}
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Contracted Rate</label>
              <input
                type="number"
                step="any"
                value={form.contractedRate}
                onChange={(e) => setForm((f) => ({ ...f, contractedRate: e.target.value }))}
                className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white"
                placeholder="0.0000"
              />
              {errors.contractedRate && (
                <p className="text-xs text-red-400 mt-1">{errors.contractedRate}</p>
              )}
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Maturity Date</label>
              <input
                type="date"
                value={form.maturityDate}
                onChange={(e) => setForm((f) => ({ ...f, maturityDate: e.target.value }))}
                className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white"
              />
              {errors.maturityDate && (
                <p className="text-xs text-red-400 mt-1">{errors.maturityDate}</p>
              )}
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Status</label>
              <select
                value={form.status}
                onChange={(e) => setForm((f) => ({ ...f, status: e.target.value as HedgeStatus }))}
                className="w-full bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white"
              >
                <option value="Active">Active</option>
                <option value="Expired">Expired</option>
                <option value="Settled">Settled</option>
              </select>
            </div>
          </div>
          <div className="flex justify-end gap-2 pt-2">
            <Button variant="ghost" onClick={() => setShowForm(false)}>
              Cancel
            </Button>
            <Button onClick={handleSave}>{editingId ? 'Save Changes' : 'Add Position'}</Button>
          </div>
        </div>
      </Modal>

      {/* Delete Confirmation */}
      <Modal isOpen={deleteId !== null} onClose={() => setDeleteId(null)}>
        <div className="p-6 space-y-4">
          <h2 className="text-lg font-bold text-white">Delete Position</h2>
          <p className="text-slate-400">Are you sure? This cannot be undone.</p>
          <div className="flex justify-end gap-2">
            <Button variant="ghost" onClick={() => setDeleteId(null)}>
              Cancel
            </Button>
            <Button
              className="bg-red-600 hover:bg-red-700"
              onClick={() => deleteId && handleDelete(deleteId)}
            >
              Delete
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useGLStore } from '@/store/glStore';
import { Button } from '@/components/ui/Button';
import { Card, CardContent } from '@/components/ui/Card';
import { Repeat, ArrowRight, TrendingUp, TrendingDown } from 'lucide-react';

const RATES: Record<string, Record<string, number>> = {
  USD: {
    EUR: 0.92,
    GBP: 0.79,
    JPY: 149.5,
    CHF: 0.88,
    CAD: 1.36,
    AUD: 1.53,
    CNY: 7.24,
    INR: 83.12,
    BRL: 4.97,
  },
  EUR: {
    USD: 1.087,
    GBP: 0.859,
    JPY: 162.5,
    CHF: 0.957,
    CAD: 1.478,
    AUD: 1.663,
    CNY: 7.87,
    INR: 90.35,
    BRL: 5.4,
  },
  GBP: {
    USD: 1.266,
    EUR: 1.164,
    JPY: 189.2,
    CHF: 1.114,
    CAD: 1.72,
    AUD: 1.936,
    CNY: 9.16,
    INR: 105.2,
    BRL: 6.29,
  },
  JPY: {
    USD: 0.00669,
    EUR: 0.00615,
    GBP: 0.00529,
    CHF: 0.00589,
    CAD: 0.0091,
    AUD: 0.0102,
    CNY: 0.0484,
    INR: 0.556,
    BRL: 0.0333,
  },
};

const CURRENCIES = ['USD', 'EUR', 'GBP', 'JPY', 'CHF', 'CAD', 'AUD', 'CNY', 'INR', 'BRL'];

function formatCurrency(n: number, currency: string): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  }).format(n);
}

interface TranslationEntry {
  accountCode: string;
  accountName: string;
  originalAmount: number;
  translatedAmount: number;
  gainLoss: number;
}

export default function TranslationResultPage() {
  const { entries } = useGLStore();
  const navigate = useNavigate();
  const [sourceCurrency, setSourceCurrency] = useState('USD');
  const [targetCurrency, setTargetCurrency] = useState('EUR');

  const rate = useMemo(() => {
    if (sourceCurrency === targetCurrency) return 1;
    return RATES[sourceCurrency]?.[targetCurrency] ?? 1;
  }, [sourceCurrency, targetCurrency]);

  const translationData = useMemo((): TranslationEntry[] => {
    const accountMap = new Map<string, { name: string; total: number }>();
    for (const entry of entries) {
      const code = entry.accountCode || 'Unknown';
      const existing = accountMap.get(code);
      const amount = (entry.debit || 0) - (entry.credit || 0);
      if (existing) {
        existing.total += amount;
      } else {
        accountMap.set(code, { name: entry.accountName || code, total: amount });
      }
    }
    return Array.from(accountMap.entries())
      .map(([code, { name, total }]) => ({
        accountCode: code,
        accountName: name,
        originalAmount: total,
        translatedAmount: total * rate,
        gainLoss: total * rate - total,
      }))
      .sort((a, b) => a.accountCode.localeCompare(b.accountCode));
  }, [entries, rate]);

  const totals = useMemo(() => {
    const original = translationData.reduce((s, e) => s + e.originalAmount, 0);
    const translated = translationData.reduce((s, e) => s + e.translatedAmount, 0);
    return { original, translated, gainLoss: translated - original };
  }, [translationData]);

  if (entries.length === 0)
    return (
      <div className="p-12 text-center">
        <Repeat className="h-10 w-10 text-slate-400 mx-auto mb-4" />
        <h2 className="text-xl font-semibold mb-2">No Data to Translate</h2>
        <p className="text-slate-400 mb-4">Import GL data to perform currency translation.</p>
        <Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>
      </div>
    );

  return (
    <div className="p-6 space-y-6">
      <h1 className="text-2xl font-bold">Translation Results</h1>

      {/* Currency Selector */}
      <Card>
        <CardContent className="p-4">
          <div className="flex items-center gap-4 flex-wrap">
            <div>
              <label className="block text-xs text-slate-500 mb-1">Source Currency</label>
              <select
                value={sourceCurrency}
                onChange={(e) => setSourceCurrency(e.target.value)}
                className="bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white"
              >
                {CURRENCIES.map((c) => (
                  <option key={c} value={c}>
                    {c}
                  </option>
                ))}
              </select>
            </div>
            <ArrowRight className="h-5 w-5 text-slate-500 mt-4" />
            <div>
              <label className="block text-xs text-slate-500 mb-1">Target Currency</label>
              <select
                value={targetCurrency}
                onChange={(e) => setTargetCurrency(e.target.value)}
                className="bg-slate-900 border border-slate-700 rounded px-3 py-2 text-white"
              >
                {CURRENCIES.map((c) => (
                  <option key={c} value={c}>
                    {c}
                  </option>
                ))}
              </select>
            </div>
            <div className="ml-auto text-right mt-4">
              <div className="text-xs text-slate-500">Exchange Rate</div>
              <div className="text-lg font-bold tabular-nums">{rate.toFixed(6)}</div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Summary Cards */}
      <div className="grid grid-cols-3 gap-4">
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-xs text-slate-400">Original ({sourceCurrency})</div>
            <div className="text-lg font-bold">
              {formatCurrency(totals.original, sourceCurrency)}
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-xs text-slate-400">Translated ({targetCurrency})</div>
            <div className="text-lg font-bold">
              {formatCurrency(totals.translated, targetCurrency)}
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 text-center">
            <div className="text-xs text-slate-400">Translation Gain/Loss</div>
            <div
              className="text-lg font-bold flex items-center justify-center gap-1"
              style={{ color: totals.gainLoss >= 0 ? '#4ade80' : '#f87171' }}
            >
              {totals.gainLoss >= 0 ? (
                <TrendingUp className="h-4 w-4" />
              ) : (
                <TrendingDown className="h-4 w-4" />
              )}
              {formatCurrency(totals.gainLoss, targetCurrency)}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Translation Table */}
      <Card>
        <CardContent className="p-0">
          <div className="overflow-x-auto max-h-[500px] overflow-y-auto">
            <table className="w-full text-sm">
              <thead className="sticky top-0 bg-slate-900 z-10">
                <tr className="text-left text-slate-400 text-xs uppercase border-b border-slate-800">
                  <th className="px-4 py-3">Account</th>
                  <th className="px-4 py-3 text-right">Original ({sourceCurrency})</th>
                  <th className="px-4 py-3 text-right">Translated ({targetCurrency})</th>
                  <th className="px-4 py-3 text-right">Gain/Loss</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800">
                {translationData.map((e) => (
                  <tr key={e.accountCode} className="hover:bg-slate-900/50">
                    <td className="px-4 py-2">
                      <span className="font-mono text-xs text-slate-400 mr-2">{e.accountCode}</span>
                      <span className="text-slate-300">{e.accountName}</span>
                    </td>
                    <td className="px-4 py-2 text-right tabular-nums">
                      {formatCurrency(e.originalAmount, sourceCurrency)}
                    </td>
                    <td className="px-4 py-2 text-right tabular-nums font-medium">
                      {formatCurrency(e.translatedAmount, targetCurrency)}
                    </td>
                    <td
                      className="px-4 py-2 text-right tabular-nums font-medium"
                      style={{ color: e.gainLoss >= 0 ? '#4ade80' : '#f87171' }}
                    >
                      {e.gainLoss >= 0 ? '+' : ''}
                      {formatCurrency(e.gainLoss, targetCurrency)}
                    </td>
                  </tr>
                ))}
              </tbody>
              <tfoot className="sticky bottom-0 bg-slate-900 border-t border-slate-700">
                <tr className="font-bold">
                  <td className="px-4 py-3">Total</td>
                  <td className="px-4 py-3 text-right tabular-nums">
                    {formatCurrency(totals.original, sourceCurrency)}
                  </td>
                  <td className="px-4 py-3 text-right tabular-nums">
                    {formatCurrency(totals.translated, targetCurrency)}
                  </td>
                  <td
                    className="px-4 py-3 text-right tabular-nums"
                    style={{ color: totals.gainLoss >= 0 ? '#4ade80' : '#f87171' }}
                  >
                    {totals.gainLoss >= 0 ? '+' : ''}
                    {formatCurrency(totals.gainLoss, targetCurrency)}
                  </td>
                </tr>
              </tfoot>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

