            </div>
            <div>
              <label className="block text-xs font-medium text-slate-400 mb-1">Category</label>
              <Input
                value={form.category}
                onChange={(e) => setForm({ ...form, category: e.target.value })}
                placeholder="e.g. Operating Revenue"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-400 mb-1">
                Parent Account (optional)
              </label>
              <Select
                options={parentOptions}
                value={form.parentId || ''}
                onChange={(val) => setForm({ ...form, parentId: val || null })}
              />
            </div>
          </div>
          <div className="flex justify-end gap-3 mt-6">
            <Button
              variant="ghost"
              onClick={() => {
                setShowModal(false);
                resetForm();
              }}
            >
              Cancel
            </Button>
            <Button onClick={handleSubmit} disabled={Object.keys(formErrors).length > 0}>
              {editingId ? 'Save Changes' : 'Add Account'}
            </Button>
          </div>
        </div>
      </Modal>

      <Modal isOpen={deleteConfirmId !== null} onClose={() => setDeleteConfirmId(null)}>
        <div className="p-6">
          <h2 className="text-lg font-semibold mb-2">Delete Account</h2>
          <p className="text-sm text-slate-400 mb-6">
            Are you sure you want to delete this account? This action cannot be undone.
          </p>
          <div className="flex justify-end gap-3">
            <Button variant="ghost" onClick={() => setDeleteConfirmId(null)}>
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={() => deleteConfirmId && handleDelete(deleteConfirmId)}
            >
              Delete
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
}

﻿import { useLocation } from 'react-router-dom';
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useGLStore } from '@/store/glStore';
import { FileDropZone } from '@/components/ui/FileDropZone';
import { Button } from '@/components/ui/Button';
import { Card, CardContent } from '@/components/ui/Card';
import { Badge } from '@/components/ui/Badge';
import { Alert } from '@/components/ui/Alert';
import {
  ArrowLeftRight,
  Upload,
  Database,
  CheckCircle2,
  AlertTriangle,
  XCircle,
  Download,
} from 'lucide-react';

function parseCSVLine(line: string): string[] {
  const values: string[] = [];
  let current = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') inQuotes = !inQuotes;
    else if (c === ',' && !inQuotes) {
      values.push(current);
      current = '';
    } else current += c;
  }
  values.push(current);
  return values;
}

export default function DataImportPage() {
  const [helpOpen, setHelpOpen] = useState(false);

  useEffect(() => {
    document.title = 'FinPlan Pro — Data Import';
  }, []);

  const { entries, accounts, importHistory } = useGLStore();
  const navigate = useNavigate();
  const [recFile, setRecFile] = useState<File | null>(null);
  const [recData, setRecData] = useState<Record<string, string>[]>([]);
  const [recKeyCol, setRecKeyCol] = useState('');
  const [recValCol, setRecValCol] = useState('');
  const [recResult, setRecResult] = useState<{
    matching: number;
    mismatches: number;
    missing: number;
    details: { key: string; expected: number; actual: number; diff: number }[];
  } | null>(null);
  const [recError, setRecError] = useState<string | null>(null);
  const [recLoading, setRecLoading] = useState(false);

  const currentSummary = useMemo(() => {
    if (entries.length === 0) return null;
    const totalDebit = entries.reduce((s, e) => s + e.debit, 0);
    const totalCredit = entries.reduce((s, e) => s + e.credit, 0);
    return {
      totalEntries: entries.length,
      totalAccounts: accounts.length,
      totalDebit,
      totalCredit,
      lastImport: importHistory[0] || null,
    };
  }, [entries, accounts, importHistory]);

  const handleRecFile = useCallback(async (file: File) => {
    setRecError(null);
    setRecResult(null);
    setRecLoading(true);
    setRecFile(file);
    try {
      const text = await file.text();
      const lines = text.split('\n').filter((l) => l.trim());
      if (lines.length < 2) {
        setRecError('File must have a header row and at least one data row.');
        setRecLoading(false);
        return;
      }
      const headers = lines[0].split(',').map((h) => h.trim().replace(/^"|"$/g, ''));
      const data = lines.slice(1).map((line) => {
        const values = parseCSVLine(line);
        const row: Record<string, string> = {};
        headers.forEach((h, i) => {
          row[h] = (values[i] || '').trim();
        });
        return row;
      });
      setRecData(data);
      if (headers.length >= 2) {
        setRecKeyCol(headers[0]);
        setRecValCol(headers[1]);
      }
      setRecLoading(false);
    } catch (e: unknown) {
      setRecError('Failed to parse file: ' + (e instanceof Error ? e.message : String(e)));
      setRecLoading(false);
    }
  }, []);

  const runReconciliation = useCallback(() => {
    if (!recKeyCol || !recValCol || recData.length === 0 || entries.length === 0) return;
    const expectedMap = new Map<string, number>();
    entries.forEach((e) => {
      const key = e.accountCode || e.accountId;
      expectedMap.set(key, (expectedMap.get(key) || 0) + (e.debit - e.credit));
    });
    let matching = 0,
      mismatches = 0,
      missing = 0;
    const details: { key: string; expected: number; actual: number; diff: number }[] = [];
    recData.forEach((row) => {
      const key = row[recKeyCol];
      const actual = parseFloat(row[recValCol]) || 0;
      const expected = expectedMap.get(key) || 0;
      if (expected === 0) {
        missing++;
      } else if (Math.abs(expected - actual) < 0.01) {
        matching++;
      } else {
        mismatches++;
      }
      details.push({ key, expected, actual, diff: actual - expected });
    });
    setRecResult({ matching, mismatches, missing, details });
  }, [recKeyCol, recValCol, recData, entries]);

  const csvHeaders = recData.length > 0 ? Object.keys(recData[0]) : [];

  if (entries.length === 0) {
    return (
      <div className="p-12 text-center max-w-md mx-auto">
        <div className="p-4 bg-slate-800 rounded-full inline-block mb-4">
          <Upload className="h-10 w-10 text-slate-400" />
        </div>
        <h2 className="text-xl font-semibold mb-2">No Data Imported</h2>
        <p className="text-slate-400 mb-6">
          Use the GL Upload page to import your financial data first, then come here to reconcile
          against external reports.
        </p>
        <Button onClick={() => navigate('/data/gl-upload')}>
          <Upload className="h-4 w-4 mr-2" />
          Go to GL Upload
        </Button>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <div className="flex items-center justify-between mb-6">
            <h1 className="text-2xl font-bold">Data Import & Reconciliation</h1>
            <button
              onClick={() => setHelpOpen(true)}
              className="p-2 hover:bg-slate-800 rounded-full text-slate-500 hover:text-white transition-colors"
              aria-label="Help"
            ></button>
          </div>
          <p className="text-sm text-slate-400 mt-1">
            Verify your imported data against source files
          </p>
        </div>
        <Button variant="secondary" onClick={() => navigate('/data/gl-upload')}>
          <Upload className="h-4 w-4 mr-2" />
          Import New Data
        </Button>
      </div>

      {currentSummary && (
        <Card>
          <CardContent className="p-4">
            <h3 className="font-semibold mb-2">Current Data Summary</h3>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div>
                <div className="text-xs text-slate-400">Total Entries</div>
                <div className="text-lg font-bold">
                  {currentSummary.totalEntries.toLocaleString()}
                </div>
              </div>
              <div>
                <div className="text-xs text-slate-400">Total Accounts</div>
                <div className="text-lg font-bold">{currentSummary.totalAccounts}</div>
              </div>
              <div>
                <div className="text-xs text-slate-400">Total Debits</div>
                <div className="text-lg font-bold text-blue-400">
                  {new Intl.NumberFormat('en-US', {
                    style: 'currency',
                    currency: 'USD',
                    minimumFractionDigits: 0,
                  }).format(currentSummary.totalDebit)}
                </div>
              </div>
              <div>
                <div className="text-xs text-slate-400">Total Credits</div>
                <div className="text-lg font-bold text-green-400">
                  {new Intl.NumberFormat('en-US', {
                    style: 'currency',
                    currency: 'USD',
                    minimumFractionDigits: 0,
                  }).format(currentSummary.totalCredit)}
                </div>
              </div>
            </div>
            {currentSummary.lastImport && (
              <div className="mt-2 text-xs text-slate-500">
                Last import: {currentSummary.lastImport.filename} on{' '}
                {new Date(currentSummary.lastImport.timestamp).toLocaleDateString()}
              </div>
            )}
          </CardContent>
        </Card>
      )}

      <Card>
        <CardContent className="p-4">
          <div className="flex items-center gap-2 mb-4">
            <ArrowLeftRight className="h-5 w-5 text-blue-400" />
            <h3 className="font-semibold">Data Reconciliation</h3>
          </div>
          <p className="text-sm text-slate-400 mb-4">
            Upload a CSV file from your source system to compare against imported data. The
            reconciliation will check account-level balances.
          </p>
          <FileDropZone onFile={handleRecFile} accept=".csv" />
          {recError && (
            <Alert type="error" title="Reconciliation Error" message={recError} className="mt-4" />
          )}
          {recData.length > 0 && (
            <div className="mt-4 space-y-4">
              <div className="p-3 bg-slate-900 rounded-lg border border-slate-800">
                <p className="text-sm text-slate-400 mb-2">
                  {recData.length.toLocaleString()} rows loaded from {recFile?.name}. Select columns
                  to match:
                </p>
                <div className="flex gap-3 items-center">
                  <div>
                    <label className="block text-xs text-slate-500 mb-1">Account Key Column</label>
                    <select
                      className="bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm"
                      value={recKeyCol}
                      onChange={(e) => setRecKeyCol(e.target.value)}
                    >
                      {csvHeaders.map((h) => (
                        <option key={h} value={h}>
                          {h}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs text-slate-500 mb-1">Balance Column</label>
                    <select
                      className="bg-slate-800 border border-slate-700 rounded px-3 py-2 text-sm"
                      value={recValCol}
                      onChange={(e) => setRecValCol(e.target.value)}
                    >
                      {csvHeaders.map((h) => (
                        <option key={h} value={h}>
                          {h}
                        </option>
                      ))}
                    </select>
                  </div>
                  <Button
                    className="mt-5"
                    onClick={runReconciliation}
                    disabled={!recKeyCol || !recValCol}
                  >
                    <ArrowLeftRight className="h-4 w-4 mr-2" />
                    Run Reconciliation
                  </Button>
                </div>
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {recResult && (
        <Card>
          <CardContent className="p-4">
            <h3 className="font-semibold mb-3">Reconciliation Results</h3>
            <div className="grid grid-cols-3 gap-4 mb-4">
              <div className="p-3 bg-green-900/20 rounded-lg border border-green-800/30 text-center">
                <CheckCircle2 className="h-5 w-5 text-green-400 mx-auto mb-1" />
                <div className="text-xl font-bold text-green-400">{recResult.matching}</div>
                <div className="text-xs text-green-400/70">Matching</div>
              </div>
              <div className="p-3 bg-red-900/20 rounded-lg border border-red-800/30 text-center">
                <XCircle className="h-5 w-5 text-red-400 mx-auto mb-1" />
                <div className="text-xl font-bold text-red-400">{recResult.mismatches}</div>
                <div className="text-xs text-red-400/70">Mismatches</div>
              </div>
              <div className="p-3 bg-yellow-900/20 rounded-lg border border-yellow-800/30 text-center">
                <AlertTriangle className="h-5 w-5 text-yellow-400 mx-auto mb-1" />
                <div className="text-xl font-bold text-yellow-400">{recResult.missing}</div>
                <div className="text-xs text-yellow-400/70">Missing</div>
              </div>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-left text-slate-400 text-xs uppercase border-b border-slate-800">
                    <th className="pb-3 pr-4">Account Key</th>
                    <th className="pb-3 pr-4 text-right">Expected (GL)</th>
                    <th className="pb-3 pr-4 text-right">Actual (File)</th>
                    <th className="pb-3 pr-4 text-right">Difference</th>
                    <th className="pb-3">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-800">
                  {recResult.details
                    .filter((d) => d.expected !== 0 || d.actual !== 0)
                    .map((d) => {
                      const status =
                        d.expected === 0
                          ? 'missing'
                          : Math.abs(d.diff) < 0.01
                            ? 'match'
                            : 'mismatch';
                      return (
                        <tr
                          key={d.key}
                          className={`hover:bg-slate-900/50 ${status === 'mismatch' ? 'bg-red-900/10' : status === 'missing' ? 'bg-yellow-900/10' : ''}`}
                        >
                          <td className="py-3 pr-4 font-mono text-xs">{d.key}</td>
                          <td className="py-3 pr-4 text-right tabular-nums">
                            {new Intl.NumberFormat('en-US', {
                              style: 'currency',
                              currency: 'USD',
                              minimumFractionDigits: 0,
                            }).format(d.expected)}
                          </td>
                          <td className="py-3 pr-4 text-right tabular-nums">
                            {new Intl.NumberFormat('en-US', {
                              style: 'currency',
                              currency: 'USD',
                              minimumFractionDigits: 0,
                            }).format(d.actual)}
                          </td>
                          <td
                            className={`py-3 pr-4 text-right tabular-nums font-medium ${Math.abs(d.diff) < 0.01 ? 'text-slate-400' : d.diff > 0 ? 'text-green-400' : 'text-red-400'}`}
                          >
                            {new Intl.NumberFormat('en-US', {
                              style: 'currency',
                              currency: 'USD',
                              minimumFractionDigits: 0,
                              signDisplay: 'exceptZero',
                            }).format(d.diff)}
                          </td>
                          <td className="py-3">
                            {status === 'match' && (
                              <Badge variant="default" className="text-[10px]">
                                Match
                              </Badge>
                            )}
                            {status === 'mismatch' && (
                              <Badge variant="destructive" className="text-[10px]">
                                Mismatch
                              </Badge>
                            )}
                            {status === 'missing' && (
                              <Badge variant="secondary" className="text-[10px]">
                                Missing
                              </Badge>
                            )}
                          </td>
                        </tr>
                      );
                    })}
                </tbody>
              </table>
            </div>
            <div className="mt-4 flex justify-end">
              <Button size="sm" variant="ghost">
                <Download className="h-3.5 w-3.5 mr-1.5" />
                Export Differences
              </Button>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

﻿import { useLocation } from 'react-router-dom';
import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useGLStore } from '@/store/glStore';
import { Skeleton } from '@/components/ui/Skeleton';
import { Button } from '@/components/ui/Button';
import { Select } from '@/components/ui/Select';
import { Card, CardContent } from '@/components/ui/Card';
import { Badge } from '@/components/ui/Badge';
import { BarChart3, TrendingUp, TrendingDown, Minus, Search } from 'lucide-react';

function formatCurrency(n: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(n);
}

export default function GLAccountAnalysisPage() {
  const [helpOpen, setHelpOpen] = useState(false);

  useEffect(() => {
    document.title = 'FinPlan Pro — G L Account Analysis';
  }, []);

  const { entries, accounts, accountAnalysis, isLoading, analyzeAccount } = useGLStore();
  const navigate = useNavigate();
  const [selectedAccountId, setSelectedAccountId] = useState('');

  const accountOptions = useMemo(
    () => [
      { value: '', label: 'Select an account...' },
      ...accounts.map((a) => ({ value: a.id, label: a.code + ' — ' + a.name })),
    ],
    [accounts]
  );

  const accountStats = useMemo(() => {
    if (!selectedAccountId || entries.length === 0) return null;
    const filtered = entries.filter(
      (e) => e.accountId === selectedAccountId || e.accountCode === selectedAccountId
    );
    if (filtered.length === 0) return null;
    const totalDebit = filtered.reduce((s, e) => s + e.debit, 0);
    const totalCredit = filtered.reduce((s, e) => s + e.credit, 0);
    const monthMap = new Map<string, { debit: number; credit: number; count: number }>();
    filtered.forEach((e) => {
      const month = e.period || e.date.slice(0, 7);
      if (!month) return;
      const g = monthMap.get(month) || { debit: 0, credit: 0, count: 0 };
      g.debit += e.debit;
      g.credit += e.credit;
      g.count++;
      monthMap.set(month, g);
    });
    const monthlyTotals = Array.from(monthMap.entries())
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([month, g]) => ({
        month,
        debit: g.debit,
        credit: g.credit,
        net: g.debit - g.credit,
        count: g.count,
      }));
    const maxNet = Math.max(...monthlyTotals.map((m) => Math.abs(m.net)), 1);
    return {
      totalDebit,
      totalCredit,
      netChange: totalDebit - totalCredit,
      transactionCount: filtered.length,
      monthlyTotals,
      maxNet,
      avgPerMonth: monthlyTotals.length > 0 ? (totalDebit - totalCredit) / monthlyTotals.length : 0,
    };
  }, [entries, selectedAccountId]);

  const handleAccountChange = (value: string) => {
    setSelectedAccountId(value);
    if (value) {
      analyzeAccount(value);
    }
  };

  if (entries.length === 0) {
    return (
      <div className="p-12 text-center max-w-md mx-auto">
        <div className="p-4 bg-slate-800 rounded-full inline-block mb-4">
          <BarChart3 className="h-10 w-10 text-slate-400" />
        </div>
        <h2 className="text-xl font-semibold mb-2">No GL Data</h2>
        <p className="text-slate-400 mb-6">
          Import General Ledger data first to analyze individual accounts.
        </p>
        <Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <div className="flex items-center justify-between mb-6">
            <h1 className="text-2xl font-bold">Account Analysis</h1>
            <button
              onClick={() => setHelpOpen(true)}
              className="p-2 hover:bg-slate-800 rounded-full text-slate-500 hover:text-white transition-colors"
              aria-label="Help"
            ></button>
          </div>
          <p className="text-sm text-slate-400 mt-1">
            {entries.length.toLocaleString()} total entries across {accounts.length} accounts
          </p>
        </div>
      </div>

      <Card>
        <CardContent className="p-4">
          <label className="block text-xs font-medium text-slate-400 mb-1.5">Select Account</label>
          <div className="flex gap-3 items-center">
            <div className="flex-1 max-w-md">
              <Select
                options={accountOptions}
                value={selectedAccountId}
                onChange={handleAccountChange}
                placeholder="Search or select an account..."
              />
            </div>
            {selectedAccountId && (
              <Button
                size="sm"
                variant="ghost"
                onClick={() => {
                  setSelectedAccountId('');
                }}
              >
                Clear
              </Button>
            )}
          </div>
        </CardContent>
      </Card>

      {!selectedAccountId && (
        <div className="text-center py-12 text-slate-500">
          <Search className="h-8 w-8 mx-auto mb-2 opacity-50" />
          <p>Select an account above to view detailed analysis.</p>
        </div>
      )}

      {isLoading && selectedAccountId && (
        <div className="space-y-4">
          <Skeleton variant="rectangular" height={100} />
          <Skeleton variant="rectangular" height={200} />
        </div>
      )}

      {!isLoading && selectedAccountId && !accountStats && (
        <div className="p-12 text-center max-w-md mx-auto">
          <h2 className="text-lg font-semibold mb-2">No Transactions Found</h2>
          <p className="text-slate-400">
            The selected account has no transactions in the current data set.
          </p>
        </div>
      )}

      {accountStats && (
        <>
          <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
            <Card>
              <CardContent className="p-4 text-center">
                <div className="text-xs text-slate-400 mb-1">Total Debits</div>
                <div className="text-lg font-bold tabular-nums text-blue-400">
                  {formatCurrency(accountStats.totalDebit)}
                </div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-4 text-center">
                <div className="text-xs text-slate-400 mb-1">Total Credits</div>
                <div className="text-lg font-bold tabular-nums text-green-400">
                  {formatCurrency(accountStats.totalCredit)}
                </div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-4 text-center">
                <div className="text-xs text-slate-400 mb-1">Net Change</div>
                <div
                  className={`text-lg font-bold tabular-nums ${accountStats.netChange >= 0 ? 'text-green-400' : 'text-red-400'}`}
                >
                  {formatCurrency(accountStats.netChange)}
                </div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-4 text-center">
                <div className="text-xs text-slate-400 mb-1">Transactions</div>
                <div className="text-lg font-bold tabular-nums">
                  {accountStats.transactionCount.toLocaleString()}
                </div>
              </CardContent>
            </Card>
            <Card>
              <CardContent className="p-4 text-center">
                <div className="text-xs text-slate-400 mb-1">Avg Monthly</div>
                <div className="text-lg font-bold tabular-nums">
                  {formatCurrency(accountStats.avgPerMonth)}
                </div>
              </CardContent>
            </Card>
          </div>

          <Card>
            <CardContent className="p-4">
              <h3 className="font-semibold mb-4">Monthly Trend</h3>
              {accountStats.monthlyTotals.length === 0 ? (
                <p className="text-slate-500 text-sm text-center py-4">No monthly data available</p>
              ) : (
                <div className="space-y-2">
                  {accountStats.monthlyTotals.map((m) => {
                    const barWidth = (Math.abs(m.net) / accountStats.maxNet) * 100;
                    const isPositive = m.net >= 0;
                    return (
                      <div key={m.month} className="flex items-center gap-3 text-sm">
                        <span className="w-16 text-xs text-slate-400 shrink-0">{m.month}</span>
                        <div className="flex-1 flex items-center gap-2">
