          <FileDropZone onFile={handleFile} accept=".csv,.xlsx,.xls" />
        </div>
      )}

      {step === 1 && (
        <Card>
          <CardContent>
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-semibold">Map Columns</h3>
              <span className="text-xs text-slate-400">
