              </span>
            </div>
            {csvColumns.length > 0 && (
              <GLColumnMapper
                csvColumns={csvColumns}
                mappings={mappings}
                onMap={handleMap}
                onAutoMap={handleAutoMap}
              />
            )}
            {csvColumns.length === 0 && (
              <div className="text-center py-8 bg-slate-900 rounded-lg border border-dashed border-slate-800">
                <AlertCircle className="h-8 w-8 text-slate-500 mx-auto mb-2" />
