  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(n);
}

export default function BoardPackPage() {
  const [helpOpen, setHelpOpen] = useState(false);
    
  useEffect(() => {
    document.title = 'FinPlan Pro — Board Pack';
  }, []);

  const { entries } = useGLStore();
  const { budgets } = useBudgetStore();
  const navigate = useNavigate();

  const report = useMemo(() => {
    if (entries.length === 0) return null;
    const revenue = entries.filter(e => (e.accountCode || '').startsWith('4'))
      .reduce((s, e) => s + (e.debit - e.credit), 0);
    const expenses = entries.filter(e => (e.accountCode || '').startsWith('5') || (e.accountCode || '').startsWith('6'))
      .reduce((s, e) => s + Math.abs(e.debit - e.credit), 0);
    const assets = entries.filter(e => (e.accountCode || '').startsWith('1'))
      .reduce((s, e) => s + (e.debit - e.credit), 0);
    const liabilities = entries.filter(e => (e.accountCode || '').startsWith('2'))
      .reduce((s, e) => s + (e.credit - e.debit), 0);
    const equity = entries.filter(e => (e.accountCode || '').startsWith('3'))
      .reduce((s, e) => s + (e.credit - e.debit), 0);
    const netIncome = revenue - expenses;
    const totalBudget = budgets.reduce((s, b) => s + (b.totalAmount || 0), 0);
    return { revenue, expenses, netIncome, assets, liabilities, equity, grossMargin: revenue > 0 ? ((revenue - expenses) / revenue) * 100 : 0, totalBudget, budgetCount: budgets.length, entryCount: entries.length };
  }, [entries, budgets]);

  const handleExportPDF = () => {
    if (!report) return;
    const data = {
      headers: ['Section', 'Category', 'Amount'],
      rows: [
        ['P&L', 'Revenue', formatCurrency(report.revenue)],
        ['P&L', 'Expenses', formatCurrency(report.expenses)],
        ['P&L', 'Net Income', formatCurrency(report.netIncome)],
        ['BS', 'Total Assets', formatCurrency(report.assets)],
        ['BS', 'Total Liabilities', formatCurrency(report.liabilities)],
        ['BS', 'Total Equity', formatCurrency(report.equity)]
      ]
    };
    ExportEngine.exportToPDF(data, { title: 'Board Pack', companyName: 'FinPlan Pro', includeTimestamp: true });
  };

  const handleExportExcel = () => {
    if (!report) return;
    const data = {
      headers: ['Section', 'Category', 'Amount'],
      rows: [
        ['P&L', 'Revenue', report.revenue],
        ['P&L', 'Expenses', report.expenses],
        ['P&L', 'Net Income', report.netIncome],
        ['BS', 'Total Assets', report.assets],
        ['BS', 'Total Liabilities', report.liabilities],
        ['BS', 'Total Equity', report.equity]
      ]
    };
    ExportEngine.exportToExcel(data, { title: 'Board_Pack_Export' });
  };

  if (entries.length === 0) {
    return (
      <div className="p-12 text-center max-w-md mx-auto">
        <div className="p-4 bg-slate-800 rounded-full inline-block mb-4">
          <FileText className="h-10 w-10 text-slate-400" />
        </div>
        <h2 className="text-xl font-semibold mb-2">No Data</h2>
        <p className="text-slate-400 mb-6">Import GL data to generate the Board Pack.</p>
        <Button onClick={() => navigate('/data/gl-upload')}>Import Data</Button>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-8 animate-fade-in">
      {/* 1. Cover Section */}
      <div className="text-center py-10 border-b border-slate-800">
        <h1 className="text-4xl font-black tracking-tight mb-2">BOARD PACK</h1>
        <p className="text-slate-400 font-medium uppercase tracking-widest text-sm">
          {new Date().toLocaleDateString('en-US', { month: 'long', year: 'numeric' })} · FINANCIAL REVIEW
        </p>
      </div>

      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold">Executive Summary</h2>
          <p className="text-sm text-slate-400 mt-1">High-level financial performance and health KPIs</p>
        </div>
        <div className="flex gap-2">
          <Button size="sm" variant="ghost" onClick={handleExportPDF} aria-label="Export PDF">
            <FileIcon className="h-3.5 w-3.5 mr-1.5" />
            PDF
          </Button>
          <Button size="sm" variant="ghost" onClick={handleExportExcel} aria-label="Export Excel">
            <TableIcon className="h-3.5 w-3.5 mr-1.5" />
            Excel
          </Button>
        </div>
      </div>

      {/* 2. Exec Summary (4 KPIs) */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card><CardContent className="p-4 text-center">
          <div className="text-[10px] font-bold uppercase tracking-widest text-slate-500 mb-1">Revenue</div>
          <div className="text-xl font-black text-green-400 tabular-nums">{report ? formatCurrency(report.revenue) : '-'}</div>
        </CardContent></Card>
        <Card><CardContent className="p-4 text-center">
          <div className="text-[10px] font-bold uppercase tracking-widest text-slate-500 mb-1">Expenses</div>
          <div className="text-xl font-black text-red-400 tabular-nums">{report ? formatCurrency(report.expenses) : '-'}</div>
        </CardContent></Card>
        <Card><CardContent className="p-4 text-center">
          <div className="text-[10px] font-bold uppercase tracking-widest text-slate-500 mb-1">Net Income</div>
          <div className={'text-xl font-black tabular-nums ' + (report && report.netIncome >= 0 ? 'text-green-400' : 'text-red-400')}>
            {report ? formatCurrency(report.netIncome) : '-'}
          </div>
        </CardContent></Card>
        <Card><CardContent className="p-4 text-center">
          <div className="text-[10px] font-bold uppercase tracking-widest text-slate-500 mb-1">Gross Margin</div>
          <div className="text-xl font-black tabular-nums">{report ? report.grossMargin.toFixed(1) + '%' : '-'}</div>
        </CardContent></Card>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* 3. P&L Summary */}
        <Card>
          <CardContent className="p-4">
            <h3 className="font-bold text-sm uppercase tracking-wider mb-4 text-slate-400">P&L Summary</h3>
            <table className="w-full text-sm" role="grid" aria-label="Profit and Loss Summary">
              <tbody className="divide-y divide-slate-800">
