                <tr role="row"><td className="py-2 text-slate-300" role="gridcell">Total Expenses</td><td className="py-2 text-right tabular-nums text-red-400" role="gridcell">{report ? formatCurrency(report.expenses) : '-'}</td></tr>
                <tr className="font-bold border-t-2 border-slate-700" role="row">
                  <td className="py-3 text-white" role="gridcell">NET INCOME</td>
                  <td className={'py-3 text-right tabular-nums ' + (report && report.netIncome >= 0 ? 'text-green-400' : 'text-red-400')} role="gridcell">
                    {report ? formatCurrency(report.netIncome) : '-'}
                  </td>
                </tr>
              </tbody>
            </table>
          </CardContent>
        </Card>

        {/* 4. BS Summary */}
        <Card>
          <CardContent className="p-4">
            <h3 className="font-bold text-sm uppercase tracking-wider mb-4 text-slate-400">Balance Sheet Summary</h3>
            <table className="w-full text-sm" role="grid" aria-label="Balance Sheet Summary">
              <tbody className="divide-y divide-slate-800">
                <tr role="row"><td className="py-2 text-slate-300" role="gridcell">Total Assets</td><td className="py-2 text-right tabular-nums text-blue-400" role="gridcell">{report ? formatCurrency(report.assets) : '-'}</td></tr>
                <tr role="row"><td className="py-2 text-slate-300" role="gridcell">Total Liabilities</td><td className="py-2 text-right tabular-nums text-red-400" role="gridcell">{report ? formatCurrency(report.liabilities) : '-'}</td></tr>
                <tr role="row"><td className="py-2 text-slate-300" role="gridcell">Total Equity</td><td className="py-2 text-right tabular-nums text-green-400" role="gridcell">{report ? formatCurrency(report.equity) : '-'}</td></tr>
