import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { User, AuthState } from '../types';
import { masterStorage } from '../utils/masterStorage';

export const useAuthStore = create<AuthState>()(
  persist(
    (set) => ({
      user: null,
      accessToken: null,
      refreshToken: null,
      isAuthenticated: false,
      isLoading: false,
      mfaRequired: false,
      activeEntityId: '',
      error: null,

      login: async (email: string, _password: string) => {
        set({ isLoading: true, error: null });
        try {
          await new Promise((r) => setTimeout(r, 500)); // simulate network delay
          set({ isLoading: false, isAuthenticated: false, user: null, accessToken: null });
          throw new Error('Backend not connected — login is disabled in offline mode.');
        } catch (error) {
          set({ isLoading: false, error: (error as Error).message });
          throw error;
        }
      },

      logout: () => {
        set({
          user: null,
          accessToken: null,
          refreshToken: null,
          isAuthenticated: false,
          isLoading: false,
          mfaRequired: false,
          activeEntityId: '',
          error: null,
        });
      },

      setUser: (user: User) => set({ user }),
      setRefreshToken: (token: string | null) => set({ refreshToken: token }),

      switchEntity: (entityId: string) => set({ activeEntityId: entityId }),

      setError: (error) => set({ error }),
      clearError: () => set({ error: null }),
      setLoading: (isLoading) => set({ isLoading }),
    }),
    {
      name: 'auth-store',
      storage: masterStorage,
    }
  )
);

