describe('migrateScenarioStore', () => {
  let cube: CubeEngine;

  beforeEach(() => {
    cube = createTestCube();
  });

  it('should migrate scenarios with metrics', () => {
    const data = {
      scenarios: [
        {
          id: 'scn-1',
          name: 'Base Case',
          type: 'Base',
          probability: 0.5,
          isActive: true,
          calculatedMetrics: {
            revenue: 1000000,
            ebitda: 200000,
            netIncome: 150000,
            cashFlow: 180000,
            headcount: 50,
            burnRate: 50000,
            runway: 24,
            grossMargin: 0.4,
            ebitdaMargin: 0.2,
          },
        },
      ],
    };
